(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["ga"]={"g-flurpruefung":["Cad atá san áireamh in iniúchadh amhairc agus feidhmiúil sula dtosaíonn tú ar an obair?","Roimh an gcéad mhisean den lá.","Seiceáil leibhéal an bhreosla agus dath na feithicle amháin.","Seiceáil coscáin, stiúrtha, forcanna, boinn agus gléasanna sábháilteachta de réir na dtreoracha oibriúcháin.","Déan tiomáint tástála leis an ualach a ardaíodh.","Áirítear leis an iniúchadh laethúil na codanna agus na feidhmeanna a bhaineann le sábháilteacht de réir na dtreoracha oibriúcháin."],"g-rueckhalt":["Conas a dhéileálann tú leis an gcóras srianta tiománaithe atá ann faoi láthair?","Tá córas srianta éigeantach ag an trucail forklift.","Bain úsáid as i gceart é agus tú ag tiomáint.","Bain úsáid as ach amháin ar urlár míchothrom.","Déan é a dhíghníomhachtú le haghaidh turais ghearr.","Ní mór na córais srianta atá beartaithe a úsáid i gcomhréir le treoracha an mhonaróra; cuireann siad cosaint ar leith ar fáil i gcás teagmhais tipping."],"g-mangelmelden":["Cad a bhaineann le forklift le forc damáiste?","Agus tú ag seiceáil, tugann tú faoi deara tine lúbtha go soiléir.","Más féidir, tabhair an t-ualach ar an stán eile.","Ná tiomáin ach ualaí solais go dtí an chéad seirbhís eile.","Ná húsáid an forklift agus cuir an locht in iúl don duine atá freagrach.","Is féidir le trealamh láimhseála ualaigh damáiste theip; Ní mór lochtanna a bhaineann le sábháilteacht a mhúchadh go dtí go soiléirítear iad."],"g-einweisung":["Aistríonn tú chuig forklift le rialuithe éagsúla. Cad atá ag teastáil roimh úsáid?","Ní hionann an oibríocht agus an fheithicil a bhí agat roimhe seo.","Teagasc a bhaineann le feiste agus comhlíonadh na dtreoracha oibriúcháin.","Is leor i gcónaí míniú gairid ó chomhghleacaí nach bhfuil baint aige leis.","Gan aon eolas breise má tá ceadúnas forklift agat.","Ní chuirtear cáilíocht ghinearálta in ionad na treorach is gá ar an bhfeiste a úsáidtear i ndáiríre."],"g-anbaugeraet":["Ba cheart duit ceangaltán a úsáid. Cad a dhéanann tú seiceáil ar dtús?","Athraíonn píosa trealaimh nua an bealach a mbailítear an t-ualach.","Cibé an n-oireann an ceangaltán ceadú na feithicle agus an t-ualach incheadaithe.","Ach amháin an féidir an gléas a cheangal go radhairc.","Cibé an féidir an ceangaltán a shuiteáil gan doiciméadú.","Is féidir le ceangaltáin an acmhainn ualaigh agus an t-ionad ualaigh atá fágtha a athrú; Ní mór ceaduithe agus faisnéis faoi thoilleadh ualaigh a sheiceáil."],"g-diagramm":["Cén fáth a bhfuil an léaráid acmhainne ualaigh uait?","Tá ualach trom i láthair le lár an domhantarraingthe i bhfad amach.","Chun an bealach is giorra a chinneadh.","Chun an t-ualach uasta is incheadaithe a mheas ag brath ar an airde ardaithe agus an t-ionad ualaigh.","Chun cumas an umar a chinneadh.","Braitheann ualaí ceadaithe, i measc rudaí eile, ar achar an ionaid ualaigh agus an airde ardaithe."],"g-lastschwerpunkt":["Cad a tharlaíonn go hiondúil nuair a bhogann lár an domhantarraingthe níos faide ar aghaidh?","A ualach fada protrudes i bhfad os comhair na forcanna.","Féadfaidh an acmhainn ualaigh incheadaithe laghdú.","Tá an cumas iompair ag méadú i gcónaí.","Níl aon tionchar ag an achar ar an nóiméad tipping.","Méadaíonn achar níos mó ón ionad ualaigh an nóiméad tipping agus féadann sé an acmhainn ualaigh incheadaithe a laghdú."],"g-gabelabstand":["Conas ba chóir do na forcanna pailléad oiriúnach a phiocadh suas?","Ba mhaith leat pailléad cothrom luchtaithe a phiocadh suas.","Leis na toiní chomh gar agus is féidir agus gan ach ar chúinne amháin.","Le achar chomh mór go leideanna an phailléid anonn go dtí an taobh.","Le spásáil stáin oiriúnach agus dóthain focharráiste agus limistéar tacaíochta.","Ní mór an t-ualach a thacú go daingean agus chomh cothrom agus is féidir trasna na bhforcanna."],"g-schieflast":["Tá ualach cruachta go héagobhsaí. Cad atá ceart?","Is féidir le boscaí cairtchláir titim nuair a thógtar iad.","Tosaigh go mall; cobhsaíonn an muirear é féin.","Sula dtógann tú an t-ualach, déan é a dhaingniú go leordhóthanach nó cuir le chéile arís é.","Ardaigh an t-ualach os cionn airde an chinn ionas nach dtiocfaidh sé ar an mbealach.","Is féidir le lasta scaoilte nó éagobhsaí titim agus daoine a chur i mbaol; bearta sábháilteachta a dhéanamh ar dtús."],"g-personen":["An féidir duine a ardú ar ghnáthfhorcanna?","Tá comhghleacaí ag iarraidh solas a bhaint amach.","Sea, má chaitheann an comhghleacaí clogad.","Ní féidir, ní féidir le daoine ach áiseanna ainmnithe agus ceadaithe a úsáid de réir riachtanas speisialta.","Sea, mura nglactar ach le airde beag.","Ní ardán oibre pearsanta iad na gnáthfhorcanna; Tá daoine a iompar agus a ardú faoi réir riachtanais speisialta."],"g-transporthoehe":["Cén chaoi a n-iompraíonn tú pailléad de ghnáth?","Tá an bóthar soiléir agus cothrom.","Leis an ualach ardaithe ach amháin chomh fada agus is gá agus de réir na dtreoracha oibriúcháin.","Agus an t-ualach ardaithe chomh hard agus is féidir a fheiceáil níos fearr.","Agus an crann ardaithe claonta go láidir ar aghaidh, beag beann ar an ualach.","Laghdaíonn suíomh iompair íseal an baol tipping agus imbhuailtí; Tá treoracha an fheiste cinntitheach."],"g-kurvenfahrt":["Cén fáth a bhfuil sé contúirteach cúinneáil go tapa le trucail ardaitheora?","Ba mhaith leat a scoir go tapa cosán caol.","Toisc draenann sé ach an ceallraí níos tapúla.","Toisc go stiúrann an forklift go huathoibríoch níos fearr.","Toisc go mbíonn tionchar ag fórsaí cliathánach ar chobhsaíocht agus go bhféadfadh siad a bheith ina gcúis le tipping.","Nuair a bhíonn cúinne á dhéanamh, tagann fórsaí breise i bhfeidhm; ní mór an luas a choigeartú leis an ualach agus na coinníollacha."],"g-ladebruecke":["Cad a dhéanann tú seiceáil sula dtiomáineann tú isteach ar dhroichead luchtaithe?","Ba chóir duit tiomáint i trucail.","Díreach cibé an bhfuil cuma leathan go leor ar an gcosán.","Acmhainn ualaigh, tacaíocht shlán agus cosaint in aghaidh aistriú chomh maith leis an bhfeithicil a dhaingniú.","Díreach cibé an bhfuil an soilsiú ar siúl.","Ní mór droichid lódála agus feithiclí a dhaingniú in aghaidh gluaiseachta agus a bheith oiriúnach don ualach."],"g-fussgaenger":["Conas a iompraíonn tú féin ag crosbhealach mearbhallach le coisithe?","Tá srian ar naisc amhairc.","Tiomáin ar luas cuí, stop más gá agus cinntigh infheictheacht shábháilte.","Éiligh an ceart slí i gcónaí agus ualach á iompar.","Just a honk agus a choinneáil ag tiomáint.","Tá riachtanais speisialta cosanta ag coisithe; Ní mór luas, infheictheacht agus cumarsáid a chur in oiriúint do bhealach an tráchta."],"g-batterieladen":["Cad ba cheart duit aird ar leith a thabhairt air nuair a bhíonn ceallraí tiomána á mhuirearú?","Úsáidtear stáisiún muirir ceallraí.","Is féidir an suíomh muirir a roghnú beag beann ar threoracha an mhonaróra.","Ceadaítear lasracha oscailte fad is atá an trucail ina stad.","Limistéar luchtaithe oiriúnach, aeráil leordhóthanach agus sonraíochtaí an mhonaróra chomh maith le cosaint dóiteáin agus pléascadh.","Nuair a bhíonn tú ag muirearú, is féidir le guaiseacha eascairt as fuinneamh leictreach, gáis agus ceimiceáin; ní mór cloí leis na bearta cosanta a chuirtear ar fáil."],"h-beauftragt":["Cad iad na coinníollacha faoina gceadaítear ardán oibre ón aer a oibriú go neamhspleách?","Ba cheart duit ardán oibre a úsáid sa chuideachta.","Má tá ceadúnas tiomána gluaisteán agat.","Má tá tú oiriúnach, treoir nó cáilithe agus coimisiúnaithe ag an bhfostóir.","Má tá ardán oibre feicthe agat riamh.","Ní mór don fhostóir oiriúnacht, cáilíochtaí agus tascanna a chinntiú de réir riachtanais oibríochtúla."],"h-vorpruefung":["Cad ba chóir a sheiceáil sula dtosaíonn tú ag obair leis an ardán oibre aerga?","Bhí an stáitse amuigh thar oíche.","Tástáil amhairc agus fheidhmiúil de réir threoracha an mhonaróra, lena n-áirítear feistí sábháilteachta.","Díreach dath agus aois an stáitse.","Cibé an bhfuil an t-ábhar oibre ar an ardán cheana féin.","Roimh úsáid, ní mór an meaisín, na rialuithe, na feidhmeanna éigeandála agus an damáiste infheicthe a sheiceáil de réir na dtreoracha oibriúcháin."],"h-tragfaehigkeit":["Cén fhaisnéis a chinneann an t-ualach ceadaithe ar an gciseán oibre?","Ba mhaith le beirt uirlisí breise a thabhairt leo.","Tá cead ag daoine an meáchan iomlán incheadaithe a mheas.","Ní áirítear ach meáchan an duine is troime.","Ní mór an tsonraíocht acmhainne ualaigh do dhaoine, uirlisí agus ábhar a shárú.","Tagraíonn an t-ualach ainmniúil don ualach iomlán incheadaithe, lena n-áirítear aon ábhar a iompraítear."],"h-untergrund":["Cad a cheapann tú roimh stáitse a bhunú le tacaí?","Tá tú ag obair in aice le limistéar líonta.","Ach amháin laistigh de teacht ar an borradh.","Seiceáil cumas ualachiompartha agus cothrom an fhodhromchla chomh maith le tacaíocht oiriúnach de réir na dtreoracha.","Ar an líon tacaíochtaí sínte is ísle is féidir.","Is féidir le cobhsaíocht a bheith mar thoradh ar thalamh neamhleor nó tacaíocht míchuí."],"h-wind":["Cuireann gaoth láidir isteach. Conas a dhéanann tú é?","Bhfaighidh tú féin le céim amuigh faoin aer.","Breathnaigh ar theorainneacha an mhonaróra agus má sháraítear iad, stop an oibríocht nó ísligh an ciseán go sábháilte.","Déan an t-ardán a leathnú chomh fada agus is féidir ionas go mbeidh sé níos cobhsaí.","Ná freagairt ach amháin má thiteann rudaí scaoilte.","Is teorainneacha úsáide iad na coinníollacha gaoithe a cheadaíonn an monaróir; Is féidir le gaoth fórsaí breise contúirteacha a chruthú."],"h-strom":["Caithfidh tú oibriú in aice le líne cumhachta lastuas. Cad atá ríthábhachtach?","Tá líne beo sa limistéar oibre.","Tagann clogad in ionad achar sábháilte a choinneáil.","Just a leithlisiú an chiseán agus ag obair gan comhordú.","Soiléiriú a dhéanamh ar an limistéar contúirte agus cinntigh achair chosanta riachtanacha nó bearta oiriúnacha eile.","Tá flashover leictreach indéanta freisin gan teagmháil dhíreach; Ní mór bearta cosanta riachtanacha a chinneadh roimh thús na hoibríochta."],"h-notablass":["Cén fáth ar gá a bheith ar eolas faoin nós imeachta um ísliú éigeandála?","Is féidir teip ar an ngnáthrialú.","Mar sin, i gcás mífheidhme, is féidir tarrtháil shábháilte de réir an fheiste.","Ionas go ritheann an gléas níos tapúla i ngnáthoibriú.","Chun tástáil rialta a athsholáthar.","Ní mór rialuithe éigeandála, ísliú éigeandála agus coincheapa tarrthála a bheith ar eolas agus feidhmiúil roimh úsáid."],"h-gelaender":["Conas airde breise a bhaint amach sa chiseán oibre?","Tá pointe montáis díreach thar do bhaint amach.","Tóg isteach ar an gclaí ciseán.","Cuir bord ar an ráille.","Úsáid ardán oiriúnach le dóthain airde oibre; ná tóg ar ráillí.","Cuireann dreapadh an chlaí nó ingearchlónna seiftithe an chosaint titim i mbaol."],"h-psaga":["Cad iad na ceanglais a bhaineann le trealamh cosanta titime pearsanta?","Úsáideann tú ardán oibre a soláthraítear córas srianta dó.","Is leor i gcónaí aon phointe ancaire lasmuigh den chiseán.","Breathnaigh ar mheasúnú riosca, ar fhaisnéis an mhonaróra agus ar na pointí oiriúnacha ancaire.","Ná húsáid aon urrús má tá ráille ag an gciseán.","Is leis an measúnú riosca, le tógáil na céime agus leis na treoracha oibriúcháin a chinnfear cibé acu atá agus cé acu TCP atá riachtanach."],"h-verfahren":["An féidir an chéim a bhogadh leis an ardán ardaithe?","Tá an t-ionad oibre cúpla méadar ar shiúl.","Ach amháin má cheadaíonn an tsamhail agus na coinníollacha oibriúcháin é de réir threoracha an mhonaróra.","I gcónaí, chomh fada agus a choimeádann gach duine ar.","Ní féidir, gan aird ar dhearadh agus formheas an déantóra.","Braitheann an ghluaiseacht sa suíomh ardaithe ar an bhfeiste agus ní cheadaítear é ach amháin laistigh de na coinníollacha oibriúcháin ceadaithe."],"h-kollision":["Cad is gá a eagrú agus tú ag obair in aice le craenacha nó meaisíní eile?","D'fhéadfadh páirteanna gluaisteacha teacht ar an gciseán oibre.","Ní dhéanfaidh aon ní; tá an ciseán oibre le feiceáil i gcónaí.","Tiomáin an ciseán oibre thar na meaisíní eile i gcónaí.","Comhordú a dhéanamh ar réimsí oibre chun imbhuailtí nó pointí pinch a sheachaint.","Éilíonn oibriú meaisín comhuaineach próisis oibre chomhordaithe agus cosaint i gcoinne imbhuailtí nó jamming."],"h-einstieg":["Conas a théann tú isteach sa chiseán oibre nó a fhágann tú?","Sroicheann tú an ciseán ag leibhéal na talún.","Tóg thar an ráille taobh amuigh.","Tríd an rochtain atá beartaithe a bheith in áit shábháilte de réir na dtreoracha oibriúcháin.","Trí dréimire curtha in aice leis agus an borradh sínte.","Ní mór cloí leis an rochtain atá beartaithe agus le treoracha an mhonaróra; Cruthaíonn dreapadóireacht neamhrialaithe an baol go dtitfidh sé."],"h-defekt":["Ní oibríonn an tsaoráid stad éigeandála. Cad atá tú a dhéanamh?","Gheobhaidh tú amach an locht le linn na cigireachta.","Ná húsáid an t-ardán agus tuairiscigh an locht.","Lean ort ag obair má tá na gnáthrialuithe ag obair.","Téipeáil an lasc ionas nach n-oibreoidh aon duine é.","Is locht a bhaineann le sábháilteacht é teip feiste sábháilteachta agus cuireann sé cosc ​​ar oibriú sábháilte."],"h-sicht":["Ní féidir gluaiseacht na tiomána a fheiceáil mar gheall ar chonstaic. Conas a théann tú faoi?","Ba cheart duit céim shoghluaiste a bhogadh.","Tiomáin go mall gan infheictheacht.","Díreach ag brath ar an táscaire achar.","Stop gluaiseacht agus cinntigh infheictheacht nó teagasc sábháilte de réir na dtreoracha oibriúcháin.","Roimh an nós imeachta, ní mór suirbhé a dhéanamh go sábháilte ar dhaoine, ar chonstaicí agus ar bhealaí tráchta."],"h-rettung":["Cad atá i gceist le pleanáil imscartha agus tú ag obair ar airde níos airde?","Úsáidtear an stáitse i gceantar iargúlta.","An ré oibre atá beartaithe amháin.","Coincheap tarrthála oiriúnach le daoine inrochtana, oilte agus nósanna imeachta ísliú éigeandála.","An toimhde go ndéanfaidh an roinn dóiteáin aon fhadhb a réiteach láithreach.","Ní mór tarrtháil éifeachtach a eagrú roimh ré, fiú má theipeann ar na gnáthrialuithe."],"k-befaehigung":["Cad atá ag teastáil chun craein a oibriú go neamhspleách?","Tá fostaí nua ceaptha dul i mbun oibre craein.","Oiriúnacht agus cáilíochtaí riachtanacha, teagasc agus sannadh comhfhreagrach.","Is leor ceadúnas tiomána gluaisteán.","Is leor faire uair amháin.","Ní fhéadfar obair chraenacha a shannadh ach do dhaoine cáilithe agus údaraithe; Tá teagasc trealaimh mar chuid de."],"k-funktionspruefung":["Cad a thógann sé chun an craein a sheiceáil roimh thús an shift?","Glacann tú craein faoi dhíon ar láimh.","Léigh an t-am reatha ar an ainmchlár.","Seiceáil feidhmeanna a bhaineann le sábháilteacht agus lochtanna infheicthe de réir na dtreoracha oibriúcháin.","Tástáil an craein leis an ualach uasta gan seiceáil.","Is é is aidhm don rialú oibríochtúil éigeantach lochtanna contúirteacha a aithint go luath."],"k-traglast":["Cad é an tábhacht a bhaineann leis an acmhainn ualaigh incheadaithe?","Tá ualach le tógáil.","Is moladh neamhcheangailteach é.","Ní bhaineann sé ach nuair a bhíonn an hook tarraingthe siar go hiomlán.","Ní ceadmhach an acmhainn ualaigh incheadaithe don riocht oibriúcháin faoi seach a shárú.","Féadfaidh ualaí ceadaithe do chineálacha áirithe craenacha a bheith ag brath ar gha, suíomh an bhorrtha agus an armáil."],"k-personen":["Cad a bhaineann le daoine faoi ualaí ar fionraí?","Bogtar an t-ualach thar limistéar oibre.","Ní mór an limistéar contúirte a choinneáil soiléir; níl cead ag aon duine céim faoin ualach ar fionraí.","Ligeann clogad duit fanacht go díreach faoi.","Ceadaítear crosairí gearra má tá an craein ag gluaiseacht go mall.","Tá baol ann go dtitfidh agus go mbrisfidh ualaí ar fionraí; Caithfear daoine a choinneáil amach as an limistéar contúirte."],"k-signale":["Ní fheiceann tú an t-ionsaitheoir agus faigheann tú comharthaí contrártha. Cad atá tú a dhéanamh?","Níl an chumarsáid soiléir.","Lean ar aghaidh leis an ordú tiomána deiridh.","Stop an ghluaiseacht agus soiléirigh an chumarsáid go soiléir.","Socraigh an t-ualach níos tapúla, gan dul i gcomhairle.","Éilíonn gluaiseachtaí ualaigh sábháilte comharthaí soiléire agus cumarsáid shoiléir."],"k-sicht":["Cé a thabharfaidh tacaíocht le linn iompair mura féidir leis an oibreoir craein an cosán ualaigh a fheiceáil go hiomlán?","Doiléir colún halla an cosán.","Duine a tharlaíonn pas a fháil gan comhaontú roimh ré.","Aon duine; níl ach an duán tábhachtach.","Duine oiriúnach, oilte le tuiscint shoiléir aontaithe.","Mura bhfuil an cosán ualaigh le feiceáil, beidh treoir chuí nó réiteach sábháilte eile ag teastáil."],"k-ruck":["Cén fáth ar chóir gluaiseachtaí craenacha jerky a sheachaint?","Tosaíonn ualach trom ag luascadh.","Cruthaíonn siad strusanna dinimiciúla breise agus féadann siad an t-ualach a dhíchobhsú.","Laghdaíonn siad go bunúsach aon ghluaiseacht luascadáin.","Méadaíonn siad an acmhainn ualaigh ainmniúil i gcónaí.","Méadaíonn fórsaí luasghéaraithe agus coscánaithe an brú ar an gcraenach agus ar na sliotáin."],"k-sperrbereich":["Cad ba cheart duit a sheiceáil sula luascann tú ualach i limistéar roinnte?","Oibríonn fostaithe eile in aice láimhe.","Cibé an dtagann an t-ualach leis an gcraenach ó thaobh amhairc.","Cibé an bhfuil an limistéar contúirte daingnithe agus nach bhfuil aon duine i mbaol.","Cibé an féidir an t-ualach a iompar chomh hard agus is féidir os cionn gach duine.","Caithfidh na cosáin sclóine agus ualaigh a bheith saor ó dhaoine gan chosaint."],"k-stuetzen":["Cad atá ríthábhachtach do chraen soghluaiste le outriggers?","Bunaítear craein ar thalamh líonta go páirteach.","Díreach leithead an bhóthair.","Dath na plátaí tacaíochta.","Bonn ualachiompartha chomh maith le tacaíocht agus dáileadh ualaigh de réir treoracha suiteála agus monaróir.","Tá tionchar suntasach ag an suiteáil ar chobhsaíocht, go háirithe i gcoinníollacha na talún atá ag athrú."],"k-wetter":["Bíonn tionchar suntasach ag séideán gaoithe ar an ualach. Cad atá ceart?","Oibríonn tú lasmuigh.","Stop an ghluaiseacht go sábháilte agus breathnaigh ar na coinníollacha oibriúcháin incheadaithe.","Go tapa dlús a chur leis an ghluaiseacht.","Leanúint ar aghaidh leis an ualach a ardú in ainneoin gur sháraigh sé teorainneacha an mhonaróra.","Is féidir le gluaiseachtaí gaoithe agus luascadh an t-ualach agus an craein a dhíchobhsú; Ní mór cloí leis na teorainneacha iarratais."],"k-freileitung":["Cad a bhaineann le húsáid craenacha in aice le línte leictreacha lastuas?","D'fhéadfadh borradh nó ualach druidim leis an líne.","Le ualach neamhsheoltach, níl imréitigh neamhthábhachtach.","An limistéar contúirte agus na bearta cosanta riachtanacha a shoiléiriú leo siúd atá freagrach sula dtosaíonn tú ar an obair.","Ag brath ach ar imoibriú an oibreora craein féin.","Tá contúirtí ann ó theagmháil agus flashover voltais; teastaíonn achair chosanta sábháilte nó bearta eile."],"k-sichern":["Cad a dhéanann tú sula bhfágann tú an craein?","Cuirtear isteach ar an obair.","Lig an t-ualach ar fionraí.","Fág an craein gan faire agus an tiomántán ag rith.","Déan an t-ualach a ísliú go sábháilte agus an craein a dhaingniú de réir na dtreoracha oibriúcháin.","Ní féidir ualaí ar fionraí a fhágáil neamhrialaithe; Ní mór an craein agus an t-ualach a pháirceáil go sábháilte."],"k-lastanschlag":["Cén chaoi a bhfuil a fhios agat an bhfuil an sling a úsáidtear oiriúnach?","Ba chóir an t-ualach a ardú le strap ardaithe.","Maidir le marcáil, cumas ualaigh, riocht agus oiriúnacht don chineál ceangail.","Díreach ag dath an strap ardaithe.","Toisc go raibh sé in úsáid cheana inné.","Caithfidh cumas agus riocht luchtaithe a bheith leordhóthanach, agus na coinníollacha ceangail á gcur san áireamh."],"k-stopp":["Téann duine isteach sa chonair ualaigh gan choinne. Cad atá tú a dhéanamh?","Tá an craein ag bogadh ualach faoi láthair.","Stop an ghluaiseacht go sábháilte láithreach agus glantar an limistéar contúirte.","Tabhair comhartha rabhaidh agus lean ort ag tiomáint.","Ardaigh an t-ualach níos airde agus tiomáint thar é.","Ní mór daoine a chosaint ar ghluaiseachtaí ualaigh; Má tá baol láithreach ann, ní mór an ghluaiseacht a stopadh."],"k-neuerkran":["Gheobhaidh tú craein le rialú anaithnid. Cad atá ceart?","Tá na rialuithe difriúil ná riamh.","Bain triail as na heochracha is gnách má tá amhras ort.","Lig do dhuine eile gan oiliúint tiomáint chun tosaigh.","Faigh an treoir riachtanach a bhaineann le feiste roimh úsáid neamhspleách.","Ní mór fiú oibreoirí craenach a bhfuil taithí acu eolas ar na rialuithe sonracha a úsáidtear, ar na feistí cosanta agus na teorainneacha."],"a-kennzeichnung":["Cén chaoi a bhfuil a fhios agat an acmhainn ualaigh incheadaithe atá ag sling?","Ba mhaith leat sling a roghnú.","Boladh an ábhair.","Ar an mharcáil acmhainne ualaigh iomchuí, inléite agus faisnéis an mhonaróra.","Ar fhad an ama stórála.","Cinntear an acmhainn ualaigh incheadaithe ag coinníollacha lipéadaithe agus oibriúcháin."],"a-sichtpruefung":["Tugann tú faoi deara gearrtha soiléir sa strap ardaithe. Conas a théann tú faoi?","Tá an banna ceaptha ualach a iompar.","Ná húsáid an téip agus é a sheoladh le haghaidh tástála nó diúltaithe.","Clúdaigh an gearrtha le téip.","Ná húsáid ach é le haghaidh ualaí éadroma go háirithe.","D’fhéadfadh sé go dteipfeadh ar shlisíní teicstíle damáiste agus ní mór iad a mheasúnú de réir na gcritéar maidir le haischur."],"a-neigungswinkel":["Cad a tharlaíonn má tá uillinn claonta na snáitheanna sling níos mó ná an ingearach?","Leathnaíonn hanger dhá shnáithe amach níos mó.","Laghdaíonn fórsaí na snáithe i gcónaí.","Fanann fórsaí na snáithe mar a chéile.","Méadaíonn na fórsaí sna snáitheanna; Ní mór cloí le huillinneacha incheadaithe agus cumais ualaigh.","De réir mar a mhéadaíonn an scaipeadh, méadaíonn an fórsa teanntachta in aghaidh an tsnáithe tacaíochta."],"a-schwerpunkt":["Cén fáth ar gá duit a bheith ar an eolas faoi lár domhantarraingthe an ualaigh?","Tá an t-ualach tógtha suas go míchothrom.","Ionas go bhfanann an t-ualach cobhsaí nuair a bhíonn sé á ardú agus nach dtéann sé ró-ard go neamhrialaithe.","Chun dath na duillíní a roghnú.","Ionas gur féidir an t-ualach a rothlú níos tapúla.","Is féidir go dtiocfadh tipping, slipping nó fánaí as pointí ceangail neamhfhabhracha nó suíomh lár an domhantarraingthe."],"a-kantenschutz":["Tá strap ardaithe i gcoinne imeall comhpháirte géar. Cad ba cheart a dhéanamh?","Ba chóir an chomhpháirt a ardú.","Ardaigh an t-ualach go tapa sula ndéantar damáiste don chrios.","Bain úsáid as cosaint imeall oiriúnach agus seiceáil an cineál ceangail.","Ná glan ach an dromchla ualaigh le éadach.","Is féidir le himill ghéar damáiste a dhéanamh do shnáithíní tacaíochta; ní mór an trealamh slinging a chosaint dá réir sin."],"a-haken":["Cad a thugann tú aird air nuair a bhíonn sling á cheangal agat?","Úsáideann tú duán lasta.","Cuir an sling ar thaobh an rinn crúca.","Coinnigh an flap sábháilteachta ar oscailt go buan.","Luchtaigh an hook mar atá beartaithe i mbonn an hook agus breathnaigh ar fheistí sábháilteachta.","D'fhéadfadh ualach neamhcheadaithe ar bharr an chromáin agus easpa daingnithe a bheith mar thoradh air a bhaint de."],"a-knoten":["An féidir leat strap ardaithe atá ró-fhada le snaidhm a ghiorrú?","Ní oireann fad an stad.","Níl; Ná húsáid ach cineál oiriúnach, ceadaithe sling nó trealamh slinging oiriúnach.","Sea, má tharraingítear an snaidhm go han-daingean.","Sea, chomh fada agus atá an t-ualach ina stad faoi láthair.","Is féidir le muirmhíle slingeanna teicstíle a lagú go suntasach agus ní cheadaítear coigeartuithe seiftithe ar fhad."],"a-probehub":["Cén fáth a n-ardaítear ualach go cúramach ar dtús?","Ba mhaith leat a iompar go sábháilte.","Ionas gur féidir léi taisteal a dhéanamh chomh tapa agus is féidir.","Chun suíomh na slingeanna, cobhsaíocht agus lár an domhantarraingthe a sheiceáil.","Toisc go n-ardóidh an cumas ualaigh go huathoibríoch.","Cuidíonn an chéad stróc rialaithe le stadanna míchearta agus suímh ualaigh éagobhsaí a bhrath."],"a-lastweg":["Cá bhfuil cead ag daoine fanacht agus an t-ualach á iompar?","Bogtar an t-ualach le craein.","Go díreach faoin ualach le clogad cosanta.","Ar an ualach más féidir leo a shealbhú ar.","Lasmuigh den limistéar contúirte agus ní faoi ualaí ar fionraí.","Fiú le ceangal cúramach, tá contúirtí ann fós ó ualaí titim nó luascadh."],"a-haende":["Conas a sheachnaíonn tú gortuithe brúite agus tú ag baint scoite?","Téann an t-ualach chuig an dromchla tacaíochta.","Coinnigh na lámha agus na cosa amach as an limistéar brúite agus bain úsáid as áiseanna cuí.","Coinnigh an t-ualach le do lámh lom.","Seas idir an t-ualach agus an balla chun an suíomh a cheartú.","Eascraíonn pointí pinch contúirteacha idir an t-ualach agus an tacaíocht."],"a-vierstraenge":["Cad a bhaineann le dáileadh ualaigh ar fhionraí ceithre-chos gan cúiteamh ualaigh?","Tá ualach docht ceangailte.","Iompraíonn na ceithre shnáithe an méid céanna dosheachanta.","Gan cruthúnas ar dháileadh aonfhoirmeach, ní fhéadfar an acmhainn ualachiompartha a úsáid mar mheastachán ginearálta do cheithre shnáithe atá luchtaithe go cothrom.","Ní bhaineann uillinn an chlaonta ansin.","Is féidir luchtú snáithe míchothrom le hualaí dochta; Caithfidh an dearadh agus an acmhainn ualaigh incheadaithe é seo a chur san áireamh."],"a-chemikalien":["Cad a bhaineann nuair a úsáidtear slingeanna teicstíle i dteagmháil le ceimiceáin?","Tá tú ag obair le leacht anaithnid.","Léiríonn dath an bhanna a marthanacht go hiontaofa.","Tá gach banna teicstíle resistant do gach ceimiceán.","Seiceáil marthanacht agus faisnéis an mhonaróra; Ná húsáid modhanna mí-oiriúnacha.","Is féidir le ceimiceáin sliotáin a ionsaí agus a gcumas ualachiompartha a laghdú gan aird."],"a-aufbewahrung":["Conas a stóráiltear slingeanna tar éis iad a úsáid?","Tá an misean thart.","Glan, tirim agus cosanta ó dhamáiste de réir sonraíochtaí an mhonaróra.","bhfostú ar an talamh faoi ualach gan chosaint.","Ar aon duán géar amuigh faoin aer.","Coscann stóráil chuí caitheamh roimh am agus déanann sé iniúchadh amhairc níos éasca."],"a-auswahl":["Cad ba cheart duit aird ar leith a thabhairt air agus tú ag déileáil le hualaí íogaire nó géar-imeall?","Tá comhpháirt meaisín péinteáilte le bogadh.","Díreach an luas iompair.","Slings oiriúnacha agus bearta cosanta don dromchla ualach agus imill.","Beag beann ar an ualach, an cábla cruach céanna i gcónaí.","Caithfidh an cineál greamaithe agus an ábhair a bheith ag teacht leis an gcéimseata, leis an dromchla agus leis an nguais."],"a-abstimmung":["Níl aon radharc ag an oibreoir craein ort. Conas a thugann tú treoracha?","Sanntar thú mar ionsaitheoir.","Déanann tú tonn ar toil go dtí go dtosaíonn gluaiseacht.","Ní thugann tú ach glaoch amháin agus siúl amach.","Trí chomharthaí atá comhaontaithe go soiléir nó trí chumarsáid iontaofa eile.","Caithfidh ionsaitheoirí agus oibreoirí craenacha cumarsáid shoiléir a dhéanamh; Mura bhfuil sé soiléir, ní mór an ghluaiseacht a stopadh."],"b-qualifikation":["Cad is gá do dhuine tochaltóir hiodrálach a oibriú go sábháilte le linn oibriú?","Ba chóir do dhuine nua dul i mbun oibre ar láithreán tógála.","Cáilíochtaí cuí, teagasc a bhaineann le gléas agus sannadh riachtanach.","Ceadúnas tiomána gluaisteáin amháin.","Breathnú tapa ar an oibríocht.","Ní mór don fhostóir na cáilíochtaí riachtanacha a chinntiú agus treoir chuí a thabhairt don oibreoir don tasc."],"b-pruefung":["Cad atá san áireamh in iniúchadh laethúil meaisín?","Glacann tú ceannas ar thochaltóir.","Seiceáil an dath péint agus upholstery suíocháin.","Amharciniúchadh agus tástálacha feidhmiúla de réir na dtreoracha oibriúcháin, mar shampla i gcás sceitheadh ​​agus damáiste.","Bog an borradh ag luas iomlán go dtí go stopann sé.","D'fhéadfadh timpistí tromchúiseacha a bheith mar thoradh ar dhamáiste do na hiodrálaic, don chassis agus do na feistí sábháilteachta."],"b-leitungen":["Cad is gá a bheith ar an eolas faoi phíobáin faoi thalamh roimh thochailt?","Ba cheart duit díog a thochailt.","Níl ach thart ar dhoimhneacht an chlais tochailte atá beartaithe.","Is leor dath na marcanna os cionn na talún.","Suíomh na línte féideartha a shoiléiriú agus bearta slándála agus taiscéalaíochta oiriúnacha a chinneadh.","D'fhéadfadh iarmhairtí bagrach don bheatha a bheith ag píopaí leictreachais, gáis nó uisce má dhéantar damáiste dóibh."],"b-schwenkbereich":["Conas a chosnaíonn tú daoine i limistéar swing an tochailteora?","Piocann tú ábhar leis an mborradh.","Tóraigh amach nó déan an limistéar contúirte slán agus coinnigh daoine ar shiúl.","Sula pivoting, bog an sluasaid go mall.","Céide thar an limistéar thar na cinnirí.","Cruthaíonn forstruchtúr sclóine agus trealamh oibre guaiseacha brúite agus imbhuailte."],"b-boeschung":["Cad atá tábhachtach agus tú ag obair in aice le imeall chlais tochailte?","Tá an tochaltóir ina sheasamh ar thalamh seanbhunaithe nó líonta.","Is é an doimhneacht tochailt amháin a chinneann an socrúchán incheadaithe.","Tabhair aird ar chumas ualachiompartha agus daingniú an chiumhais chomh maith leis na hachair riachtanacha de réir an mheasúnaithe riosca.","Tiomáin chomh gar don imeall agus is féidir chun raon a shábháil.","Mura bhfuil imréiteach leordhóthanach nó talamh cobhsaí ann, féadfaidh an claífort theipeann agus féadfaidh an meaisín titim."],"b-standsicherheit":["Cén fáth a bhfuil fána agus talamh ríthábhachtach le húsáid?","Tá an láithreán tógála ar fhána.","Tá an meaisín cothrom cobhsaí ar aon dromchla.","Cuireann focharráistí rianaithe deireadh le haon bhaol diúscartha.","Is féidir le héagothroime agus fána difear do chobhsaíocht; Breathnaigh ar theorainneacha iarratais.","Braitheann cobhsaíocht agus sábháilteacht tipping ar an urlár, trealamh, ualach agus suíomh meaisín."],"b-wechselgeraet":["Cad a dhéanann tú seiceáil tar éis buicéad tochailteora a athrú ag baint úsáide as cúplóir tapa?","Suiteáladh ceangaltán nua.","Cibé an bhfuil sé faoi ghlas i gceart agus daingnithe de réir na dtreoracha oibriúcháin.","Díreach an bhfuil dath an tsluasaigh ag teacht leis.","Cibé an oibríonn na hiodrálaigh chomh ciúin agus is féidir.","Is féidir le glais lochtacha a chur faoi deara go dtiteann ceangaltáin."],"b-heben":["Cad ba cheart duit aird a thabhairt air nuair a bhíonn ualach crochta faoi shaoirse á ardú le tochaltóir?","Úsáidtear an tochaltóir le haghaidh oibríochtaí ardaithe.","Níl ach an gnáthfhórsa tochailte cinntitheach.","Breathnaigh ar an ualach ardaithe incheadaithe, ar na pointí ceangail oiriúnacha agus ar na feistí cosanta forordaithe.","Is féidir an t-ualach a chromadh ar fhiacla an bhuicéad.","Ní cheadaítear ardaithe ach amháin laistigh de na coinníollacha oibriúcháin atá beartaithe le trealamh oiriúnach."],"b-rueckwaerts":["Caithfidh tú cúlú, ach ní fheiceann tú an cosán. Cad atá ceart?","Tá oibrithe eile in aice láimhe.","Tiomáin amach go cúramach gan infheictheacht.","Just a honk agus a choinneáil ag tiomáint.","Stop, cinntigh infheictheacht agus an limistéar contúirte nó eagraigh treoracha oiriúnacha.","Níor cheart go gcuirfeadh aisiompú daoine i mbaol; tá bearta breise ag teastáil ó thaobh infheictheachta teoranta."],"b-kabel":["D'fhéadfadh an borradh teacht gar do líne cumhachta lastuas. Cad atá tú a dhéanamh?","Oibríonn tú ar shuíomh tógála daingean.","Déan an limistéar contúirte agus bearta cosanta oiriúnacha a shoiléiriú leis na daoine atá freagrach roimh ré.","Déan neamhaird den líne má tá an borradh péinteáilte.","Ná bog ach an borradh go háirithe go tapa.","Eascraíonn guaiseacha leictreacha ó theagmháil agus spléachadh; tá achair shábháilte agus bearta cosanta riachtanach."],"b-verlassen":["Conas a pháirceálann tú an tochaltóir sula bhfágann tú?","Glacann tú sos.","Fág an borradh ag snámh faoi shaoirse.","Socraigh trealamh oibre go sábháilte agus déan an meaisín a dhaingniú in aghaidh gluaiseachta agus úsáide neamhúdaraithe.","Fág an t-inneall ag rith agus an chábán ar oscailt.","Laghdaíonn trealamh oibre íslithe agus cosaint ar ghluaiseacht neamhbheartaithe an baol timpistí."],"b-hydraulik":["Tugann tú faoi deara ola hiodrálach faoi bhrú ard ar líne damáiste. Cad atá ceart?","Tá líne ag sceitheadh.","Mothaigh an sceitheadh ​​le do lámh.","Ceangail clampán nua faoi bhrú.","Múch an meaisín go sábháilte, lig don bhrú a laghdú agus socraigh go ndéanfaidh pearsanra údaraithe speisialtóireachta deisiúcháin.","Is féidir le sreabhach hiodrálacha faoi bhrú ard a bheith ina chúis le gortuithe tromchúiseacha; Ná seiceáil le haghaidh sceitheanna de láimh."],"b-unterbau":["Cad é an baol a bhaineann le tiomáint ar dhromchlaí éagobhsaí?","Bíonn an talamh bog tar éis báistí.","Is féidir leis an meaisín doirteal, sleamhnán nó barr os a chionn.","Éiríonn an tiomáint níos leithne go huathoibríoch.","Déanann sé seo an raon sclóine níos sábháilte.","Is féidir le hacmhainn ualaigh neamhleor cur isteach go mór ar chobhsaíocht agus ar shábháilteacht tiomána."],"b-arbeitsgeraet":["An féidir le duine oibriú faoi ghléas ardaithe?","Is mian le duine rud éigin a rialú faoin sluasaid.","Sea, nuair a bhíonn an t-inneall díomhaoin.","Ní féidir, gan an tacaíocht shábháilte riachtanach agus an trealamh oibre a dhaingniú.","Sea, má tá clogad sábháilteachta á chaitheamh ag an duine.","Is féidir le trealamh hiodrálacha doirteal; Teastaíonn trealamh slán oibre le haghaidh obair chothabhála."],"b-geraeteart":["Aistríonn tú ó thochaltóir hiodrálach go lódóir rotha. Cad atá ag teastáil?","Tá iompar oibríochta agus gluaiseachta difriúil.","Díreach an coisbheart céanna.","Tiomáint tástála gan treoracha.","An cháilíocht nó an treoir a theastaíonn don chineál meaisín nua.","Ní mór don cháilíocht a bheith ag teacht leis an gcineál meaisín a úsáidtear agus na ceanglais oibríochtúla ar leith."],"g-neigung":["Tá tú ag tiomáint forklift luchtaithe ar incline. Cad atá tábhachtach?","Tá grádán soiléir ag an mbealach.","Déan an t-ualach a threorú síos an cnoc i gcónaí, fiú má tá sé trom.","Treoraigh an t-ualach suas an cnoc agus cloí leis na treoirlínte oibriúcháin maidir le tiomáint ar chlaonta.","Beag beann ar an treo taistil, ardaigh an forc go dtí an t-uasmhéid.","Ar chlaonta agus ar shliocht, ní mór an t-ualach a iompar suas an cnoc i gcónaí; Ní mór an fheithicil agus na treoracha oibriúcháin a chomhlíonadh."],"g-gabelabsenken":["Cén fáth a gcaithfear an forc a ísliú agus tú ag páirceáil?","Tá an forklift páirceáilte le haghaidh sos.","Ionas gur féidir le daoine eile an forc a úsáid chun dreapadh suas.","Ionas go bhfanann an forc níos sofheicthe ó fad.","Ionas nach mbeidh riosca tuislithe nó gortaithe gan ghá leis an ualach a ardú.","Laghdaíonn gléasanna láimhseála ualaigh íslithe an baol go dtarlódh tionóiscí mar gheall ar fhorcanna atá ag brúchtadh nó gan urrús."],"g-fahrerwechsel":["Ba mhaith le comhghleacaí an forklift a fháil ar iasacht. Cad a chaithfidh a bheith i láthair?","Níl cead cainte uait ach ag an gcomhghleacaí.","Caithfidh na cáilíochtaí riachtanacha agus sainordú oibriúcháin a bheith aige.","Baineann do shannadh féin leis go huathoibríoch freisin.","Is leor ceadúnas tiomána gluaisteán príobháideach do gach gnóthas.","Tá ceannaireacht neamhspleách ceangailte le hoiriúnacht phearsanta, oiliúint, cáilíochtaí agus sannadh oibriúcháin."],"g-ladungssicherung":["Tá boscaí scaoilte, cruachta ar phailléid. Cad atá ceart?","Is féidir le bosca cairtchláir titim síos agus tú ag tiomáint.","Déan an t-ualach a dhaingniú i gcoinne slipping agus titim roimh iompar.","Ná tiomáin ach go mall ar thalamh atá go háirithe míchothrom.","Cúiteamh do bhoscaí scaoilte le seasamh forc níos airde.","Caithfidh an t-ualach a bheith cobhsaí agus daingnithe i gcoinne titim sula n-iompraítear é leis an trucail tionsclaíoch."],"g-bodenbelastung":["Os do chomhair tá brat le cumas ualachiompartha teoranta. Conas a shocraíonn tú?","Téann an bealach thar leibhéal idirmheánach.","Díreach aird a thabhairt ar mheáchan an trucail gan ualach.","Soiléiriú a dhéanamh ar an ualach urláir incheadaithe le haghaidh forklifts agus ualaí.","Tiomáin le móiminteam ionas go mbeidh an uasteorainn faoi ualach ar feadh tréimhse ama níos giorra.","Is é an rud atá ábhartha ná an strus iomlán iarbhír ar an limistéar, lena n-áirítear tionchair feithicle, ualaigh agus dinimiciúla."],"g-verkehrswege":["Trasnaíonn cosán marcáilte do chosán. Cad atá ceart?","Is féidir le coisithe rochtain a fháil ar an gcrosaire am ar bith.","Is féidir leat tosaíocht a éileamh i gcónaí leis an adharc.","Tá cead agat tiomáint thar an marcáil gan a bheith faoi deara.","Coigeartaigh do luas, tabhair aird ar choisithe agus ná lean ort ag tiomáint ach amháin nuair a bhíonn an cosán soiléir.","Ní mór bealaí tráchta a thiomáint agus aird á tabhairt ar dhaoine; Ní chuirtear comharthaí rabhaidh in ionad infheictheacht shábháilte agus bealach soiléir."],"g-parkbremse":["Páirceáil tú forklift ar thalamh cothrom. Cad a chuimsíonn sin?","Ba mhaith leat suíochán an tiománaí a fhágáil ar feadh roinnt nóiméad.","Páirceáil, cuir coscán páirceála i bhfeidhm agus slán in aghaidh úsáide neamhúdaraithe.","Ná fág an fheithicil ach i suíomh neodrach.","Fág an forc ag airde an chinn ionas nach mbaineann aon duine leis.","Sula bhfágann sé, ní mór an trucail a stopadh go sábháilte agus a dhaingniú i gcoinne gluaiseachta neamhbheartaithe."],"g-typenschild":["Cén fhaisnéis atá ceangailteach nuair a thagann sé chun an t-ualach ar trucail forklift?","Ba mhaith leat meaisín trom a phiocadh suas.","An acmhainn ualaigh measta bunaithe ar mhéid na feithicle.","Faisnéis an mhonaróra sa léaráid acmhainne ualaigh nó ualaigh.","Meáchan an phailléid dheireanach a iompraíodh.","Déantar an t-ualach incheadaithe a chinneadh ag faisnéis an mhonaróra agus braitheann sé, i measc rudaí eile, ar an ionad ualaigh agus ar an airde ardaithe."],"g-tore":["Téann tú i dtreo pasáiste íseal le forklift. Cad atá á sheiceáil agat?","Tá ualach ard ar an bhfeithicil.","Cibé an bhfuil pasáiste lena n-áirítear an t-ualach agus ceangaltán indéanta go sábháilte.","Níl ach airde an iompair forc gan ualach.","Cibé an féidir leat tiomáint níos tapúla sula ndúnann an geata.","Roimh pasáistí, ní mór airde agus leithead soiléir chomh maith le toisí an ualaigh agus na feithicle a chur san áireamh."],"g-reifen":["Le linn do sheiceála laethúil aimsíonn tú bonn a bhfuil damáiste mór déanta dó. Cad atá tú a dhéanamh?","Tá damáiste a bhaineann le sábháilteacht le feiceáil ar an mbonn.","Tiomáineann tú go mall go dtí do choinne cothabhála rialta.","Méadaíonn tú brú na mbonn agus leanann tú ag tiomáint.","Ní thógann tú an fheithicil i bhfeidhm agus ní thuairiscíonn tú an damáiste.","Is féidir le boinn damáiste dochar a dhéanamh do chobhsaíocht agus do láimhseáil; ní mór an locht a shoiléiriú roimh úsáid."],"h-absperren":["Siúlann fostaithe anuas faoi d’ardán oibre. Cad atá riachtanach?","Tá an baol ann ó uirlisí titim.","Limistéar oiriúnach cosanta nó srianta faoin ionad oibre.","Níl ann ach fógra nuair a théann tú thart ar dtús.","Stóráil uirlisí chomh fada ar shiúl ó imeall an chiseáin agus is féidir.","Ní mór limistéar oibre faoi stáisiúin oibre ardaithe a dhaingniú ó chontúirt ó chodanna titim."],"h-werkzeuge":["Conas a iompraíonn tú uirlisí sa chiseán oibre?","Tá gá le roinnt uirlisí beaga ar airde.","Cuir iad go scaoilte ar an ráille ionas go mbeidh siad in ann teacht go héasca orthu.","Déan iad a stóráil agus a dhaingniú ar bhealach nach dtitfidh siad síos nó nach gcuireann siad bac ar oibriú.","Ceangail leis an taobh amuigh den ráille i do phóca.","Is féidir le rudaí scaoilte titim agus daoine a chur i mbaol; tá gá le stóráil shlán."],"h-abstuetzung":["Seasann tacaíocht ar chlúdach dúnphoill. Cad is gá a sheiceáil?","Ba mhaith leat an t-ardán a ardú.","Cinntigh go bhfuil an clúdach tirim.","Cibé an féidir an t-ualach a ionsú go sábháilte ag an bpointe sin.","Cibé ní gá na tacaí eile a úsáid.","Caithfidh an fho-ithir agus na limistéir teagmhála a bheith in ann na fórsaí tacaíochta a ionsú go sábháilte; Ní mór clúdaigh a mheasúnú ar leithligh."],"h-notaus":["Cathain ar cheart an gléas stad éigeandála a úsáid?","Tarlaíonn gluaiseacht contúirteach láithreach.","Ach amháin ag deireadh athrú rialta.","Chun stop a chur i mbaol géar de réir na dtreoracha oibriúcháin.","Mar ionadach ar an ísliú pleanáilte.","Úsáidtear an stad éigeandála chun an chontúirt a sheachaint, ní an gnáthrialú nó an gnáth-mhúchadh."],"h-schraegstellung":["Freagraíonn an rabhadh tilt céim. Conas a imoibríonn tú?","Tá an meaisín ar dhromchla claonta.","Déanann tú neamhaird den rabhadh ag airde oibre ísle.","In ainneoin an rabhaidh, thiomáineann tú chuig an suíomh ardaithe is airde.","Stopann tú agus tugann tú an stáitse i riocht sábháilte de réir threoracha an déantóra.","Féadfaidh rabhaidh tilt cobhsaíocht neamhleor a léiriú; níor cheart go gcuirfeadh gluaiseachtaí breise leis an mbaol."],"h-umgebung":["Cad is gá a eagrú agus tú ag socrú in aice le limistéar tráchta?","Is féidir le feithiclí teagmháil a dhéanamh leis an stáitse.","Cosaint ar imbhuailtí agus treoir chuí tráchta.","Swing an ciseán oibre chomh fada agus is féidir thar an mbóthar.","Níl le déanamh ach glaoch rabhaidh sula dtosaíonn tú.","Ní mór ardáin oibre aeir a chosaint ar imbhuailtí le húsáideoirí bóithre; ní mór an tsuiteáil a dhaingniú dá réir sin."],"h-ueberlast":["Spreagtar an rabhadh ró-ualaithe sa chiseán. Cad atá tú a dhéanamh?","Tugadh cuireadh do uirlisí breise.","Críochnaigh an obair ar luas níos airde.","Socraigh an t-ualach ciseán incheadaithe agus lean treoracha an mhonaróra.","Múch an comhartha rabhaidh go buan.","Ní mór an t-ualach uasta is incheadaithe ar an gciseán, lena n-áirítear daoine agus ábhar, a shárú."],"h-quetschen":["Tiomáineann tú an ciseán gar faoin díon. Cén chontúirt atá tábhachtach go háirithe?","Is beag spás atá fágtha os cionn an chiseáin.","Clampáil nó crushing idir an ciseán agus an struchtúr.","Go n-ídíonn an t-inneall níos mó breosla.","Go n-aisiompaíonn an treo taistil go huathoibríoch i gcónaí.","Is féidir le spásanna daingean os cionn nó in aice leis an gciseán oibre a bheith ina chúis le gortuithe tromchúiseacha."],"h-stromausfall":["Fanann an stáitse ag airde mór gan príomhthiomáint. Cad atá ceart?","Ní fhreagraíonn an gnáth-rialú ciseán a thuilleadh.","Dhreap tú síos an borradh gan sábháilteacht.","Fanann tú go dtí deireadh do sheal gan a bheith curtha ar an eolas.","Tús a chur leis an tarrtháil ullmhaithe ag baint úsáide as daoine oilte agus ísliú éigeandála.","Ní mór tarrtháil shábháilte a phleanáil le haghaidh cur isteach; Ní mór go mbeadh a fhios ag daoine oilte feidhmeanna éigeandála."],"h-transportstellung":["Conas a shocraíonn tú an stáitse le haghaidh iompair?","Lódáiltear an t-ardán aeroibre ar fheithicil oiriúnach.","Tabhair an borradh agus an t-ardán isteach sa suíomh iompair de réir na dtreoracha oibriúcháin.","Ceangail an t-ardán síos chomh fada amach agus is féidir.","Fág na tacaí leathnaithe ionas go dtógann sé níos mó spáis.","Tá an suíomh iompair forordaithe agus an daingniú ualaigh bunaithe ar shonraíochtaí an mhonaróra agus an iompair."],"k-bremsprobe":["Cad a léiríonn tástáil fheidhmiúil ar an gcoscán craein roimh úsáid?","Ba mhaith leat a bheith in ann ualach a choinneáil slán.","Cibé an stopann an coscán agus an gcoimeádann sé an ghluaiseacht mar a bhí beartaithe.","Díreach cibé an n-oibríonn an soilsiú cábáin.","Cibé an féidir leis an hook ualach a sheasamh go huathoibríoch.","Roimh úsáid, ní mór feidhmeanna a bhaineann le sábháilteacht a sheiceáil de réir na sonraíochtaí."],"k-schraegzug":["An féidir leat ualach cliathánach a tharraingt ar uillinn leis an gcraenach?","Níl an hook go hingearach os cionn an ualaigh.","Sea, má tá cúlchiste ualaigh fós ag an gcraenach.","Ní féidir, ní féidir ualaí a tharraingt trí úsáid a bhaint as tarraingt trasnánach neamhcheadaithe.","Sea, má tá na sliotáin go háirithe gearr.","Is féidir le tarraingt trasnánach gluaiseachtaí neamhrialaithe agus brú breise a chur ar an gcraenach agus ar na sliotáin."],"k-verhakt":["Tá ualach ar crochadh ar an bhfostruchtúr. Cad atá ceart?","Braitear friotaíocht nuair a bhíonn tú ardaithe.","Coinníonn tú ardaithe go dtí go dtagann sé ar shiúl.","Bogann tú an t-ualach leataobhach.","Stopann tú agus baintear an ceangal nó an bac go sábháilte.","Níor cheart ualaí greamaithe a bheith stróicthe le fórsa, mar go bhféadfadh fórsaí do-ghlactha teacht chun cinn."],"k-anzuheben":["Cad a dhéanann tú a sheiceáil agus ualach ar fionraí á ardú go hachomair den chéad uair?","Ardaíonn an t-ualach cúpla ceintiméadar ón talamh.","Cibé an bhfuil sé hangs i cothromaíocht agus an stad slán.","Cibé an féidir le duine iad féin a chur go díreach faoin ualach.","Cibé an dtiocfaidh an craein níos cobhsaí trí chasadh go tapa.","Úsáidtear ardú rialaithe gairid chun ceangaltán, cothromaíocht agus iompar sábháilte ualaigh a sheiceáil."],"k-lastweg":["Cá háit ar cheart an bealach iompair ualach craein a bheith?","Tá go leor ionad oibre faoin gcosán ualaigh féideartha.","Más féidir, thuas stáisiúin oibre áitithe.","Ar chosán pleanáilte, soiléir gan aon daoine i mbaol.","I gcónaí trasnánach tríd an limistéar is gnóthaí.","Ní mór bealaí ualaigh a eagrú ar bhealach nach mbeidh daoine i mbaol mar gheall ar ualaí ar fionraí."],"k-signalverlust":["Briseann an nasc raidió leis an mharascail. Cad atá tú a dhéanamh?","Ní féidir leat an cosán ualaigh féin a fheiceáil.","Leanann tú ar aghaidh leis an ngluaiseacht go mall.","swing tú go turgnamhach sa treo roimhe seo.","Stopann tú an ghluaiseacht go dtí go bhfuil tuiscint shoiléir, shlán.","Má tá easpa cumarsáide ann, ní fhéadfaidh gluaiseacht ualaigh mearbhall leanúint ar aghaidh."],"k-haken":["Ní dhúnann an hook sábháilteachta go hiontaofa. Cad atá ceart?","Le linn na cigireachta, tugtar faoi deara dúnadh lochtach.","Ní mór an earráid a cheartú go gairmiúil roimh úsáid bhreise.","Ceanglaíonn tú an clasp go docht le carbhat cábla.","Ní úsáideann tú an dubhán ach le haghaidh ualaí éadroma.","Is féidir le gléasanna daingnithe lochtacha ar chrúcaí ualaigh a bheith ina gcúis le slingeanna a bheith neamhchúlaithe agus ní mór iad a leigheas."],"k-zugrichtung":["Cad atá tábhachtach maidir le tacaíocht ingearach ualach?","Tá an t-ualach le tógáil as meaisín.","Ba cheart an hook craein a ailíniú os cionn lár dhomhantarraingt an ualaigh.","Ba chóir an duán a shuíomh chomh taobh agus is féidir.","Ní mór an t-ualach a bhrú roimh ardú.","Seachnaíonn éifeacht fórsa atá chomh ingearach agus is féidir os cionn an ionaid ualaigh fórsaí cliathánach neamhcheadaithe agus luascadh amach neamhrialaithe."],"k-wartung":["Tugtar faoi deara torann neamhghnách meilt ar an gcraenach. Conas a théann tú faoi?","Tarlaíonn an torann nuair a ardú.","Clúdaigh suas an torann trí luas níos airde.","Cuir stop le hoibríochtaí go sábháilte, tuairiscigh lochtanna agus soiléirigh iad.","Lean ort ag obair gan fógra go dtí an sos.","Is féidir le hathruithe suntasacha damáiste a bhaineann le sábháilteacht a léiriú agus tá gá le hiniúchadh."],"k-absetzen":["Cad is gá a ráthú nuair a bhíonn ualach craein á ísliú?","Tá ualach trom suite ar dhromchla.","Féadfaidh an t-ualach a bheith neamhurraithe ar dhromchla claonta.","Baintear slingeanna fad is atá sé fós ar snámh.","Tá an t-ualach cobhsaí agus daingnithe i gcoinne tipping nó rolladh ar shiúl.","Ní féidir an t-ualach a scaoileadh ón bhfearas slinging ach amháin tar éis é a leagan síos go sábháilte agus cobhsaíocht a bheith bunaithe."],"l-schwerpunkt":["Cén fáth nach mór lár an domhantarraingthe a bheith ar eolas roimh bhualadh?","Tá meaisín múnlaithe neamhshiméadrach le hiompar.","Ionas go bhfanann an t-ualach chomh cothrom agus is féidir agus é ardaithe.","Ionas gur féidir na slingeanna a roghnú chomh fada agus is inmhianaithe.","Ionas nach mbeidh ról ag an acmhainn ualaigh incheadaithe.","Bíonn tionchar ag suíomh lár an domhantarraingthe ar an dáileadh ualaigh agus ar chothromaíocht shábháilte nuair a bhíonn tú ardaithe."],"l-etikett":["Níl lipéad acmhainne ualaigh inléite ag strap ardaithe. Cad atá ceart?","Tá an mharcáil do-aitheanta anois.","Déan meastachán ar an acmhainn ualaigh bunaithe ar an dath.","Ná húsáid an strap ardaithe go dtí go mbeidh a oiriúnacht léirithe go soiléir.","Ná húsáid ach an crios uair amháin le haghaidh ualaí beaga.","Tá marcálacha oiriúnacha ag teastáil le haghaidh slingeanna; Cuireann toilleadh iompair gan mhíniú cosc ​​ar roghnú sábháilte."],"l-kantenschutz":["Tá banna teicstíle suite thar imeall cruach géar. Cad atá riachtanach?","Tá imill ghéar ar an ualach.","Tarraing an banna chomh docht agus is féidir gan chosaint.","Déan an stróc níos tapúla.","Úsáid cosaint imeall oiriúnach nó trealamh slinging oiriúnach eile.","Is féidir le himill ghéar damáiste a dhéanamh do thaillí teicstíle nó iad a ghearradh; tá cosaint chuí ag teastáil."],"l-spreizwinkel":["Cén tionchar a bhíonn ag uillinn claonta níos mó ar an ualach ar na sliotáin?","Ardaítear ualach ag baint úsáide as dhá rópa slanting.","Ag uillinneacha níos lú fabhrach, is féidir na fórsaí sna snáitheanna a mhéadú.","Imíonn fórsaí an tsnáithe.","Níl aon tionchar ag an uillinn ar an strus.","Le uillinn stad níos lú fabhrach, is féidir na fórsaí in aghaidh an tsnáithe a mhéadú; Ní mór táblaí acmhainne ualaigh a urramú."],"l-knoten":["An féidir rópa sling a ghiorrú de réir mar is mian leis trí úsáid a bhaint as snaidhm?","Tá an rópa ró-fhada don ualach pleanáilte.","Sea, feabhsaíonn snaidhm daingean an cumas ualaigh.","Ní féidir, bain úsáid as modhanna faofa giorraithe agus ancaireachta amháin.","Sea, má tá an snaidhm daingnithe le téip.","Lagaíonn muirmhíle neamhcheadaithe na sliotáin agus athraíonn siad a n-acmhainn ualaigh incheadaithe."],"l-zeichen":["Cad a bhaineann le cumarsáid leis an duine a oibríonn an craein?","Tá an cosán ualaigh doiléir go páirteach.","Tugann roinnt daoine comharthaí éagsúla ag an am céanna.","Úsáidtear comharthaí soiléire a comhaontaíodh roimhe seo.","Ní bhíonn gá riamh le cumarsáid le craenacha raidió.","Cuireann comharthaí soiléire agus freagrachtaí soiléire cosc ​​ar ghluaiseachtaí contúirteacha míchearta."],"l-sichtpruefung":["Cathain ar cheart slingeanna a sheiceáil le haghaidh lochtanna infheicthe?","Ba mhaith leat slabhra sling a úsáid.","Roimh úsáid, tabhair aird ar aon damáiste atá le feiceáil go seachtrach.","Ach amháin má tharla timpiste cheana féin.","Ach uair amháin nuair a ceannaíodh ar dtús.","Roimh gach úsáid, ní mór an riocht oibre sábháilte a mheas; Cuireann damáiste infheicthe cosc ​​ar úsáid shábháilte."],"l-drehung":["Tosaíonn ualach ardaithe a rothlú go neamhrialaithe. Cad atá tú a dhéanamh?","Gluaiseann an t-ualach sa chonair ualaigh.","Chuir tú do lámh idir an t-ualach agus an balla.","Cuireann tú tú féin faoin ualach agus coinníonn tú greim air.","Coinníonn tú d'achar agus ligeann tú don ghluaiseacht stop a chur ar bhealach rialaithe.","Cruthaíonn gluaiseachtaí ualaigh neamhrialaithe guaiseacha brúite agus tionchair; Caithfidh daoine an limistéar contúirte a fhágáil."],"l-ablegen":["Cathain is féidir slingeanna a bhaint den ualach?","Cuirtear an t-ualach ar tristéil.","Má tá an t-ualach cobhsaí agus daingnithe in aghaidh tipping anonn nó rolladh as.","Chomh luath agus a bhaineann sé leis an talamh den chéad uair, beag beann ar a seasamh.","Agus tú fós ag hovering chun am a shábháil.","Ní féidir slingeanna a bhaint ach amháin tar éis iad a leagan síos go sábháilte agus go cobhsaí."],"l-ketten":["Tá nasc lúbtha mór ag sling slabhra. Cad atá tú a dhéanamh?","Tá an damáiste le feiceáil fiú roimh ardú.","Wrap an limistéar damáiste le sreang.","Bain an slabhra as úsáid agus seiceáil go gairmiúil é.","Ná ardaigh ach an t-ualach leath chomh hard.","Is damáiste infheicthe iad naisc slabhra dífhoirmithe a d'fhéadfadh úsáid shábháilte a chosc."],"b-einweiser":["Cad atá tábhachtach nuair a bhíonn an infheictheacht ón tochaltóir teoranta?","Déanann cuid den fhoirgneamh an limistéar tiomána doiléir.","Bearta nó treoir amhairc iomchuí agus cumarsáid shoiléir.","Just a féachaint ar an cochall.","Tiomáin tríd an limistéar sclóine cé go bhfuil sé dofheicthe.","Má chuirtear srian le hinfheictheacht, ní mór guaiseacha a chosc trí bhearta eagraíochtúla agus teicniúla breise."],"b-aushub":["Cá háit is féidir ábhar tochailte a stóráil in aice le clais tógála?","Níor cheart imeall an chlais a chur i mbaol breise.","Carn suas go díreach ar an imeall ionas go mbeidh na cabhsáin soiléir.","Stóráil ag achar sách sábháilte agus de réir sonraíochtaí láithreán tógála.","Cuir ar chladach scaoilte gan a thuilleadh tástála.","Is féidir le hábhar tochailte claífoirt agus claífort a chur i mbaol mar gheall ar ualaí breise; Ní mór achair sábháilteachta a choinneáil."],"b-personen":["An bhfuil cead ag daoine fanacht sa limistéar luascáin fad a bhíonn an tochaltóir ag bogadh?","Ba mhaith le duine a thomhas agus é ag panning.","Sea, chomh fada agus a chaitheann sí clogad sábháilteachta.","Sea, má luascann an tochaltóir go mall.","Ní féidir, caithfidh an limistéar contúirte a bheith soiléir roimh ghluaiseacht.","Tá baol mór-bhrú agus gortuithe tionchair sa limistéar sclóine; ní mór an limistéar a choinneáil soiléir."],"b-ladung":["Conas a iompraíonn tú ábhar go sábháilte le lódóir rotha?","Ba chóir sluasaid líonta a thiomáint trasna an chlóis.","Le suíomh iompair íseal oiriúnach agus cosán soiléir.","Le sluasaid ardaithe le haghaidh infheictheacht níos fearr.","Le doirse oscailte agus uillinn stiúrtha láidir.","Laghdaíonn suíomh iompair oiriúnach an baol go n-iompóidh sé agus feabhsaíonn sé cobhsaíocht tiomána."],"b-anbaupruefung":["Cad a dhéanann tú seiceáil tar éis ceangaltán a chúpláil?","Bhí sluasaid nua ceangailte.","Díreach glaineacht na péintéireachta.","An glasáil slán agus feidhm de réir na dtreoracha oibriúcháin.","Díreach an bhfuil cuma an fheiste mar an gcéanna ón taobh amuigh.","D'fhéadfadh scaoileadh neamhbheartaithe ceangaltán a bheith mar thoradh ar ghlais mhíchearta ar chúplálaithe tapa."],"b-einstieg":["Conas a théann tú isteach i gcábán an tochailteora go sábháilte?","Tá na céimeanna salach tar éis báisteach.","Tóg isteach an cábáin tríd an borradh.","Faigh ar na boilb i léim amháin.","Bain úsáid as céimeanna ainmnithe agus greim láimhe agus glan céimeanna salach.","Laghdaíonn dreapadóireachta oiriúnacha agus pointí coinneála sábháilte an baol sleamhnú agus titim."],"b-graben":["Léiríonn balla trinse scoilteanna agus é ag mionú. Cad atá ceart?","Oibríonn tú díreach in aice leis an díog.","Stop den obair agus iarr orthu siúd atá freagrach an poll tochailte a dhaingniú.","Níl ort ach tiomáint níos gaire don imeall chun an díog a dhúnadh.","Déan an trinse a dhoimhniú níos mó gan chosaint.","Féadfaidh scoilteanna agus gluaiseachtaí talún éagobhsaíocht a léiriú agus go mbeadh measúnú sábháilteachta breise ag teastáil."],"b-betanken":["Cad a thugann tú aird air agus tú ag athbhreoslú meaisín gluaiste talún?","Tá an umar beagnach folamh.","Daingnigh an t-inneall agus foinsí adhainte de réir threoracha an mhonaróra agus seachain doirteadh.","Athlíon peitreal nó díosal sa chábán i gcónaí.","Deatach agus tú ag athbhreoslaithe nuair nach mbíonn gaoth ann.","Teastaíonn bearta cosanta cuí maidir le guaiseacha dóiteáin agus comhshaoil ​​agus breosla á láimhseáil."],"b-laufwerk":["Cén fáth ar gá na rianta agus an focharráiste a sheiceáil go rialta?","Tugann tú faoi deara creathadh neamhghnách agus tú ag tiomáint.","Ionas gur féidir leis an meaisín bogadh níos tapúla.","Toisc go bhféadfadh damáiste tionchar a bheith aige ar threoir shábháilte agus ar chobhsaíocht.","Toisc go gceadaítear obair i gcónaí gan iniúchadh amhairc.","Is féidir le damáiste don tiomáint difear a dhéanamh ar inaistritheacht, ar chobhsaíocht agus ar oibriú sábháilte."],"b-einweisen":["Cad a theastaíonn agus tú ag obair in aice le trácht coisithe poiblí?","Oibríonn tochaltóir go díreach ar imeall cosáin.","Ba chóir do choisithe bogadh tríd an limistéar luascáin iad féin.","Just a bata comhartha ar an sluasaid.","Go héifeachtach stopann an limistéar contúirte agus dírigh an trácht go sábháilte.","Ní fhéadfaidh tríú páirtithe dul isteach i gcrios contúirte na meaisíní gluaiste talún; Tá gá le bacainní cuí agus ródú tráchta."],"g2-fahrweg":["Tá leacht doirte ar an mbóthar amach romhainn. Conas a théann tú faoi?","Thiomáinfeadh an forklift go díreach thar an limistéar sleamhain.","Stop ag tiomáint agus déan an láthair chontúirte a dhaingniú nó a bhaint.","Tiomáin thar an láthair chomh tapa agus is féidir agus an forc ardaithe.","Tá súil le boinn níos tirime agus leanúint ar aghaidh ag tiomáint gan athrú.","Cuireann bealaí éillithe cobhsaíocht i mbaol agus ní mór iad a dhaingniú go leordhóthanach sula dtiomáineann orthu."],"g2-sichtladung":["Cuireann pailléad ard bac ar an radharc amach romhainn. Cad atá ceart?","Caithfidh tú tiomáint chuig limistéar stórála agus ní féidir leat an bealach a fheiceáil.","Ardaigh an phailléid suas go dtí go bhfeiceann tú thíos é.","Ná tiomáin ach ag úsáid modhanna oiriúnacha, sábháilte, amhail cúlú le radharc soiléir.","Is féidir leat tiomáint go fóill ar an mbóthar gan chomhartha nó radharc soiléir.","Caithfidh an treo taistil agus infheictheacht a bheith in ann breathnóireacht shábháilte a dhéanamh ar an mbealach tráchta; Ní ceadmhach ualaí a chur in ionad iniúchadh amhairc."],"g2-fussgaengerstop":["Stopann coisí díreach in aice leis an forklift. Cad atá tú a dhéanamh?","Tá an duine laistigh den raon tiomána agus pivoting féideartha.","Scol an coisí trí luasghéarú go hachomair.","Tiomáin thar an duine leis an ualach a ardaíodh.","Stop agus gan ach leanúint ar aghaidh ag tiomáint achar sábháilte.","Ní mór do dhaoine fanacht amach as an limistéar contúirte; Más gá, ní mór cur isteach ar an turas."],"g2-hubmast":["Tugann tú faoi deara go bhfuil damáiste déanta do líne hiodrálach ar chrann an ardaitheora. Cad a bhaineann?","Feictear go bhfuil ola hiodrálach ag sceitheadh ​​as an bhfearas.","Tóg an forklift as oibriú agus tuairiscigh an damáiste.","Seiceáil an sceitheadh ​​de láimh agus tú ag ardú.","Ná tóg ach ualaí níos lú go dtí go bhfuil an t-aistriú thart.","Is féidir le gluaiseachtaí neamhrialaithe a bheith mar thoradh ar damáiste hiodrálach; ní ráthaítear úsáid shábháilte go dtí an tástáil."],"g2-lagerregal":["Ba mhaith leat pailléad a stóráil ar sheilf. Cad a dhéanann tú seiceáil ar dtús?","Tá an leibhéal seilf ard agus ní mór an cumas ualaigh a choinneáil.","Brúigh an pailléid ar an seilf chomh tapa agus is féidir.","Seiceáil an urrann seilf, meáchan luchtaithe agus spás stórála saor in aisce le haghaidh oiriúnachta.","Déan meastachán ar an meáchan iomlán bunaithe ar líon na mboscaí amháin.","Caithfidh seilfeanna agus trealamh ualachiompartha an staid ualaigh agus stórála a mheaitseáil."],"g2-batterieschaden":["Déantar damáiste do cheallraí forklift go seachtrach. Cad atá ceart?","Roimh luchtú, tugtar faoi deara scoilteanna nó sreabhach neamhghnácha.","Clúdaigh damáiste le téip ghreamaitheach agus ualach láithreach.","Lig do dhuine eile an ceallraí a mhuirearú gan é a sheiceáil.","Ná muirear nó úsáid agus cuir na speisialtóirí freagrach ar an eolas.","Cruthaíonn cadhnraí damáiste guaiseacha leictreacha agus ceimiceacha agus teastaíonn measúnú gairmiúil orthu."],"g2-fahrerkabine":["Cad a bhaineann le rudaí scaoilte i limistéar an tiománaí?","Tá uirlisí ar an urlár in aice leis na pedals rialaithe.","Bain rudaí agus coinnigh an limistéar oibriúcháin soiléir.","Ná coinnigh an uirlis ach le cos amháin agus tú ag tiomáint.","Folaigh páirteanna scaoilte faoi shuíochán an tiománaí.","Is féidir le rudaí scaoilte bac a chur ar pedalanna agus oibriú sábháilte na feithicle a dhochrú."],"g2-uebergabe":["Glacann tú forklift i ndiaidh athrú seala. Cad a chuimsíonn sin?","Ba é an uair dheireanach a d’úsáid comhghleacaí an fheithicil.","Glac leis go bhfuil na seiceálacha ar fad glactha ag an gcomhghleacaí.","Déan an t-iniúchadh riachtanach agus fiosraigh faoi lochtanna aitheanta.","Tosaigh an turas gan féachaint ar an meaisín.","Ní mór don duine atá ag glacadh seilbhe a chinntiú go bhfuil sé i riocht sábháilte roimh úsáid."],"g2-transportsicherung":["Tá réad ard scaoilte ar an phailléid. Conas a ghníomhaíonn tú?","D'fhéadfadh an t-ualach dul ar aghaidh agus coscánaithe.","Déan an forc a iompar go háirithe ard ionas go bhfanann an t-ualach cobhsaí.","Just a chur ar an curves go mall, dul díreach níos tapúla.","Socraigh an t-ualach ar bhealach cobhsaí agus slán é in aghaidh titim nó titim.","Ní mór ualaí scaoilte a chobhsú roimh an iompar ionas nach mbeidh gluaiseachtaí coscánaithe agus tiomána ina chúis le titim."],"g2-arbeitsende":["Cad atá tábhachtach le forklift gan duine ar bith?","Críochnaíonn tú do sheal agus fágann tú an ceantar.","Páirceáil an fheithicil go sábháilte agus daingnigh í in aghaidh rolladh amach agus úsáid neamhúdaraithe.","Fág an eochair isteach ionas gur féidir le comhghleacaithe an meaisín a aimsiú.","Fág an forc ag leibhéal na súl ionas go mbeidh sé le feiceáil.","Áiríonn páirceáil shábháilte láimhseáil ualaigh íslithe agus cosaint ar ghluaiseacht agus ar choimisiúnú neamhúdaraithe."],"g2-bremsweg":["Cén fáth go gcaithfidh tú aird ar leith a thabhairt ar an achar coscánaithe faoi ualach?","Iompraíonn an forklift earraí troma trí phasáiste stórais.","Déan coscán i gcónaí níos déanaí le ualach trom ná gan ualach.","Coigeartaigh an luas de réir na gcoinníollacha infheictheachta, talún agus ualaigh.","Nuair a bheidh tú ag coscánaithe, ardaigh an t-ualach go géar chun luasmhoilliú a dhéanamh níos fearr.","Bíonn tionchar ag mais agus riocht an bhóthair ar an achar stad; tá luas oiriúnaithe eochair."],"g2-rampe":["Cad a dhéanann tú seiceáil roimh dhreapadh ar rampa géar?","Féadfaidh an bealach a bheith ró-ghéar don fheithicil.","Tiomáin ar an ramp ar uasluas beag beann ar an ngrádán.","Tiomáin thar imeall an rampa agus an t-ualach ardaithe.","Seiceáil an grádán incheadaithe agus an modh oibríochta sábháilte ó shonraíochtaí na feithicle.","Ní fhéadfar ach rampaí laistigh de na teorainneacha oibriúcháin atá beartaithe a úsáid; Tá treoracha oibriúcháin agus rialú ualaigh cinntitheach."],"g2-zinke":["Tá pailléad níos leithne ná an t-achar forc. Cad is gá a chur san áireamh?","Tá sé beartaithe agat ualach neamhghnách mór a ghlacadh.","Coigeartaigh fad an fhorc agus na pointí gléasta chun freastal ar an ualach.","Ná húsáid ach stán amháin má tá an t-ualach ró-leathan.","Ardaigh an t-ualach ar uillinn go dtí go sroicheann sé an suíomh ceart.","Laghdaíonn ionsú ualaigh fiú agus oiriúnach slipping agus tipping."],"g2-betriebsanweisung":["Cén ról atá ag rialáil tráchta oibriúcháin?","Tá limistéir mharcáilte aontreo agus coisithe i bhfeidhm sa stóras.","Maidir le forklifts, ní bhaineann ach rialacha an bhóthair phoiblí.","Lean na bealaí sonraithe agus na rialacha tráchta.","Déan neamhaird de mharcálacha nuair a bhíonn an fheithicil lódáilte.","Cosnaíonn bealaí cuideachta agus rialacha sábháilteachta trácht forklift agus daoine de shiúl na gcos."],"g2-nothalt":["Imoibríonn an stiúrtha go neamhghnách agus é ag tiomáint. Cad atá ceart?","Ní féidir an fheithicil a rialú mar is gnách a thuilleadh.","Tiomáint ar luasanna níos airde chun an stiúradh a dhéanamh níos freagraí.","Déan an earráid a chúiteamh le sraontaí stiúrtha an-mhór.","Stop in áit shábháilte agus seiceáil an fheithicil.","Cuireann stiúrtha lagaithe treoir shábháilte i mbaol; níor cheart go leanfadh an meaisín d'oibriú neamhrialaithe."],"g2-anschlagkette":["Ba mhaith leat ualach atá ar crochadh faoi shaoirse a bhogadh le forklift. Cad a bhaineann?","Ba chóir go mbeadh ualach ar crochadh ar Hook faoi na forcanna.","Gan ach feiste ceadaithe agus trealamh ualachiompartha oiriúnach.","Déanfaidh aon slabhra mura bhfuil an t-ualach trom.","Clamp an slabhra go díreach idir an dá fhorc.","Athraíonn ualaí crochta go saor cobhsaíocht; Teastaíonn ceadú an mhonaróra agus áiseanna oiriúnacha."],"g2-rollenlast":["Tá comhpháirt sorcóireach neamhurraithe ar phailléid. Cad atá tú a dhéanamh?","Féadfaidh an t-ualach rolladh le linn iompair.","Cur chuige an phailléid go háirithe jerkily.","Déan an comhpháirt a dhaingniú i gcoinne rollta sula mbailítear an phailléid.","Suí na tiona ard go leor nach bhfuil an comhpháirt le feiceáil.","Teastaíonn cosaint iontaofa ar ualaí babhta nó rollta in aghaidh athruithe sa suíomh."],"g2-pruefplakette":["Cén chaoi a bhfuil a fhios agat an féidir an forklift a úsáid?","Tá greamán iniúchta greamaithe den mheaisín.","Cuirtear aon ghreamán in ionad an iniúchta amhairc laethúil i gcónaí.","Is féidir tiomáint chúramach a chur in ionad easpa imréitigh.","Chomh maith leis an bhfeithicil a sheiceáil, ní mór stádas tástála bailí agus formheas oibríochta a chur san áireamh.","Comhlíonann tástáil athfhillteach agus rialuithe oibriúcháin laethúla feidhmeanna sábháilteachta éagsúla."],"g2-licht":["Chuaigh an soilsiú sa stóras amach go tobann. Cad atá ceart?","Ní féidir leat constaicí sa chosán a fheiceáil go sábháilte a thuilleadh.","Stop ag tiomáint go dtí go mbeidh infheictheacht shábháilte ráthaithe.","Luas tiomána a mhéadú chun an limistéar dorcha a fhágáil.","Lean ort ag tiomáint agus na forcanna ardaithe gan iniúchadh amhairc.","Níor cheart bealach nach féidir breathnú amach air go sábháilte a thiomáint ar aghaidh gan bearta sábháilteachta éifeachtacha."],"g2-ueberhang":["Síneann ualach i bhfad níos faide ná taobh an fhorc. Cad atá á sheiceáil agat?","Ba mhaith leat an pailléad a iompar trí gheata caol.","Déan cúiteamh ar an teilgean cliathánach le cuar tapa.","Déan imréiteach, cobhsaíocht agus cumas ualaigh incheadaithe a mheas roimh thiomáint.","Tiomáin an t-ualach ar an luas uasta beag beann ar a chruth.","Méadaítear rioscaí imbhuailte ar bharrchrochtaí agus féadann siad cobhsaíocht agus an spás tráchta a theastaíonn a athrú."],"g2-wartungsbereich":["Tá bacainní os comhair limistéar cothabhála. Conas atá tú ag iompar?","Tá do ghnáthbhealach dúnta go sealadach.","Bog bacainní go hachomair agus tiomáint trí nach dtugtar.","Tiomáin go díreach tríd an limistéar oibre faoi ualach.","Breathnaigh ar an dúnadh agus roghnaigh bealach eile formheasta.","Ní féidir dul isteach i limistéir atá crochta nó dul tríd gan chead."],"g2-bremsprobe":["Cathain a dhéanann tástáil fheidhmiúil ar an gcoscán seirbhíse ciall?","Ullmhaíonn tú an forklift roimh obair.","Mar chuid den iniúchadh riachtanach roimh úsáid.","Déan ach amháin tar éis timpiste thromchúiseach.","Ach amháin má tá an trucail bainte amach cheana féin ardluais.","Déantar feidhmiúlacht na n-áiseanna a bhaineann le sábháilteacht a sheiceáil roimh úsáid."],"g2-fahrzeuganhaenger":["Ba mhaith leat leantóir a tharraingt le forklift. Cad atá ag teastáil?","Tá an chuideachta ag pleanáil iompair le ualach ceangailte.","Ceangail gach leantóir le forc gan seiceáil.","Breathnaigh ar fhormheas an mhonaróra, cúpláil oiriúnach agus ualach teanntachta incheadaithe.","Just a mhéadú ar an brú na mbonn agus tiomáint as.","Ní féidir traenacha a oibriú go sábháilte ach amháin laistigh de na sonraíochtaí teicniúla agus le nasc oiriúnach."],"g2-rueckfahrt":["Cad atá tábhachtach agus tú ag aisiompú leis an forklift?","Tá limistéar mearbhall sa aisle stórais.","Breathnaigh i gcónaí sa scáthán rearview amháin, beag beann ar an timpeallacht.","Tiomáin gan infheictheacht chomh fada agus a bhíonn an adharc brúite uair amháin.","Breathnaigh go sábháilte ar an mbealach agus ar limistéar na ndaoine agus, más gá, tabhair treoir dóibh.","Teastaíonn dearcadh soiléir nó bearta sábháilteachta breise éifeachtacha chun aisiompú."],"g2-lastentnahme":["Tógann tú pailléad as seilf ard. Cad atá ceart?","Seans nach bhfuil an pailéad lárnaithe.","Pioc suas an t-ualach go sábháilte agus é a chobhsú roimh ísliú.","Lig don phailléad luascadh go dtí an taobh agus tú ag tarraingt amach.","Seiceáil thíos an phailléid ardaithe féachaint an bhfuil damáiste déanta dó.","Cuireann ardú agus ísliú rialaithe cosc ​​ar ualaí titim agus gluaiseachtaí contúirteacha."],"h2-absenkweg":["Cén fáth nach mór an limistéar faoi ardán aeroibre a bheith soiléir?","Íslítear an ciseán agus cuirtear ábhair faoina bhun.","Brúigh ábhair síos leis an gciseán.","Ná coinnigh ach súil ar limistéar coise an oibreora.","Seachain an baol brúite agus imbhuailte nuair a ísliú.","Níor cheart go mbeadh aon daoine nó constaicí sa limistéar íslithe a d’fhéadfadh a bheith gafa."],"h2-transporthoehe":["Conas a bhogann tú céim shoghluaiste thar pasáiste íseal?","Tá an t-imréiteach níos ísle ná an borradh leathnaithe.","Cuir an t-ardán i riocht iompair oiriúnach de réir na dtreoracha oibriúcháin.","Fág an borradh leathnaithe agus bogadh ar aghaidh faoin uasteorainn.","Brúigh an ciseán i gcoinne thaobh an fhráma dorais.","Maidir le gluaiseachtaí taistil, caithfidh an airde iomlán agus an suíomh iompair sonraíochtaí an mhonaróra agus an sliocht a mheaitseáil."],"h2-bodenoeffnung":["Tá oscailt neamhurraithe san urlár in aice leis an stáitse. Conas a imoibríonn tú?","Tá pointe tiomána nó tacaíochta suite in aice leis an oscailt.","Cuir tacaíocht go díreach ar imeall an oscailt.","Athraigh an suíomh suiteála nó seiceáil an acmhainn ualaigh agus an daingniú go gairmiúil.","Ná clúdaigh ach an pointe contúirte le bosca cairtchláir.","Is féidir go dteipeann ar oscailtí agus ar limistéir imeall faoi ualaí tacaíochta agus ní mór iad a chur san áireamh go héifeachtach."],"h2-rettungsperson":["Cén fáth a gcaithfidh an dara duine a bheith eolach ar an nós imeachta tarrthála?","D’fhéadfadh oibreoir éirí faoi éagumas ag an mbarr.","Ionas gur féidir obair sa chiseán a dhéanamh go ginearálta gan slándáil.","Ionas gur féidir an chéim a oibriú níos tapúla ná mar a cheadaítear.","Ionas gur féidir tarrtháil shábháilte a thionscnamh i gcás éigeandála.","Ní mór cúnamh talamh-bhunaithe a chur san áireamh i gcoincheap tarrthála i gcás teipe nó éigeandála."],"h2-werkzeugabwurf":["Cad a bhaineann le huirlisí ag airde ard?","D'fhéadfadh uirlis scaoilte titim thar imeall an chiseáin.","Uirlisí slán ionas nach gcuirfidh siad duine ar bith i mbaol nó nach dtitfidh siad síos.","Níl ort ach uirlisí a chur ar an ráille chun an t-ualach a laghdú.","Más gá, caith uirlisí síos ón gciseán.","Cuireann rudaí titim i mbaol daoine thíos; Ní mór ábhar a stóráil go sábháilte."],"h2-trittstufe":["Ba chóir go mbeadh bosca mar spás breise sa chiseán. Cad atá ceart?","Seachas sin is ar éigean a shroichfidh tú an t-ionad oibre.","Cuir an bosca ar an ráille agus tóg air.","Ná tóg ar ingearchlónna seiftithe; Úsáid trealamh oiriúnach oibre.","Luchtaigh an ciseán d'aon ghnó thar an airde ceadaithe.","Cuireann ingearchlónna seiftithe isteach ar an gcosaint titime atá beartaithe agus ní cheadaítear iad."],"h2-lastverteilen":["Cad a thugann tú aird air nuair a bhíonn roinnt daoine sa chiseán oibre?","Tá beirt ag obair sa chiseán le huirlisí troma.","Breith an t-ualach bunaithe ar mhéid an uirlis amháin.","Stóráil uirlisí trom go díreach ar an ráille cosanta.","Ná sáraigh an t-ualach ciseán incheadaithe lena n-áirítear daoine agus uirlisí.","Áirítear leis an acmhainn ualaigh cheadaithe na daoine, na hábhair agus na huirlisí go léir sa chiseán."],"h2-abstuetzplatte":["Cathain a dhéantar breathnú ar shims breise le haghaidh tacaíochtaí?","Ní féidir leis an urlár suiteála ach ualach teoranta a iompar.","Más gá é seo le haghaidh dáileadh sábháilte ualaigh de réir sonraíochtaí.","Chun na tacaí a chur chomh gar agus is féidir d'imeall an chlais tógála.","Raon níos faide a úsáid gan faisnéis ón monaróir.","Tá gá le limistéir teagmhála leordhóthanacha le haghaidh fórsaí tacaíochta sábháilte."],"h2-baugrube":["Ba cheart céim a bheith suite go díreach ag imeall sloc tógála. Cad atá á sheiceáil agat?","D'fhéadfadh an fo-ithir éalaithe go cliathánach de bharr an chlais tochailte.","Leathnaigh na tacaí isteach sa chlais tochailte.","Cinntigh achar sábháilteachta dóthanach agus cumas ualachiompartha an fhodhromchla.","Ná déan an riosca a chúiteamh ach tríd an gciseán a ardú go mall.","Is féidir le claiseanna tochailte difear do chobhsaíocht de bharr fána agus teip fo-ithreach."],"h2-witterung":["Leagann oighriú isteach le linn úsáide. Conas a ghníomhaíonn tú?","Éiríonn dromchlaí rialaithe agus limistéar oibre mín.","Ardaigh an stáitse chun sneachta agus oighear a sheachaint.","Déan neamhaird de na rabhaidh chomh fada agus atá an t-ardán ar lasadh.","Cuir isteach ar an obair agus déan coinníollacha oibriúcháin a athmheasúnú de réir na dtreoracha oibriúcháin.","Féadfaidh athruithe ar an aimsir dliteanas, inoibritheacht agus teorainneacha sábháilte úsáide a athrú."],"h2-aufbaukontakt":["Cuireann tógáil cruach teorainn le cosán an chiseáin. Cad atá tábhachtach?","Nuair a bhíonn tú ag ardú tá baol ann go mbrisfear idir an ciseán agus an t-iompróir.","Déan gluaiseachtaí a phleanáil ionas nach mbeidh do chorp agus do chiseán gafa.","Déan an turas níos tapúla ionas go n-imíonn an ciseán níos tapúla.","Brúigh an tógáil leis an gciseán go dtí an taobh.","Teastaíonn breathnóireacht chúramach agus gluaiseacht rialaithe ar phointí pinn idir an t-ardán agus an timpeallacht."],"h2-sicherheitsabstand":["Cathain a chaithfear limistéar contúirte stáitse a scoráil?","Gabhann bealach iompair phoiblí faoin suíomh.","Ach amháin má tá rud tar éis titim cheana féin.","Dá bhféadfaí tríú páirtithe a chur i mbaol trí ghluaiseacht nó rudaí ag titim.","Riamh, toisc go gcoisceann an ciseán oibre gach contúirt go bunúsach.","Ní mór an limistéar faoi agus in aice leis an gcéim a chosaint ar ghuaiseacha intuartha."],"h2-korbtor":["Cad a bhaineann le doras isteach an chiseáin oibre?","Tá tú ar airde oibre cheana féin.","Fág an doras ar oscailt ionas gur féidir leat dul amach níos tapúla.","Ceangail an doras ar oscailt go buan le rópa.","Coinnigh an doras dúnta de réir na meicníochta glasála a sholáthraítear.","Tá na glais a chuirtear ar fáil mar chuid de na bearta cosanta in aghaidh titim as an gciseán oibre."],"h2-energieleitung":["Cad a bheidh i gceist mura ndéantar líne lasnairde a mhúchadh go sábháilte?","Oibríonn tú leis an ardán oibre aerga in aice leo.","Achair sábháilteachta sonraithe agus bearta cosanta riachtanacha a chinntiú.","Bog an ciseán díreach os comhair na líne chomh fada agus nach bhfuil sé i dteagmháil léi.","Iontaobhas sna boinn phlaisteacha agus oibrigh gan aon bhearnaí.","Is féidir flashovers leictreacha freisin gan teagmháil dhíreach; Tá faid sábháilteachta ag teastáil."],"h2-schwanken":["Tosaíonn an ciseán oibre ag luascadh go neamhghnách láidir. Cad atá ceart?","Ní rialaítear an ghluaiseacht a thuilleadh.","Athcheartaigh go neamhrialaithe le frithghluaiseachtaí tapa.","Stop gluaiseacht agus seiceáil cúis nó coinníollacha oibriúcháin.","Cuir daoine breise leis an gciseán chun é a dhéanamh níos troime.","Féadfaidh tonnchrith neamhghnách coinníollacha oibriúcháin mí-oiriúnacha nó mífheidhmiú a léiriú."],"h2-ladegeraet":["Déantar damáiste do chábla luchtaithe don chéim a oibrítear go leictreach. Cad atá tú a dhéanamh?","Nuair a bhíonn sé ag nascadh, tá insliú damáiste le feiceáil.","Déan teagmháil leis an damáiste le lámhainní fliuch.","Brúigh an breiseán isteach sa soicéad chomh crua agus is féidir.","Ná cuir tús leis an bpróiseas muirir agus seiceáil an cábla go gairmiúil.","Tá baol turrainge agus tine ag baint le sreangú leictreach millte."],"h2-gelaenderanbau":["An féidir leat ráille a bhaint duit féin le teacht níos gaire?","Cuireann comhpháirt cosc ​​ar dhaoine teacht ar an suíomh oibre.","Ná modhnaigh ná bain amach gléasanna cosanta i do cheann féin.","Tar éis ardú, díscriú an ráille agus é a shuiteáil níos déanaí.","Lean ort ag obair gan ráille fad is atá duine éigin ina sheasamh in aice leis.","Ní fhéadfar feistí cosanta struchtúracha a athrú gan sonraíochtaí ceadaithe agus bearta athsholáthair sábháilte."],"h2-lastkran":["An féidir an t-ardán a úsáid mar chraen chun ualach a ardú?","Ba chóir ábhar a iompar ar crochadh faoi shaoirse in aice leis an gciseán oibre.","Aon uair a bhíonn an meáchan níos lú ná do mheáchan coirp féin.","Ach amháin má cheadaíonn an monaróir agus an trealamh go sainráite an úsáid speisialta seo.","Níl ort ach crúca a cheangal leis an ábhar ráille agus ardaitheoir.","Ní dheartar ardáin oibre aerga go huathoibríoch le haghaidh obair chraein nó ualaí crochta breise."],"h2-arbeitsvorbereitung":["Cad a bhaineann le hullmhú do shuíomh nua?","Níl a fhios agat an láithreán tógála fós.","Déan meastachán ar an bhfad go dtí an carrchlós is gaire duit.","Beag beann ar an timpeallacht, é a leathnú go hiomlán láithreach.","Déan measúnú ar ghuaiseacha, ithir, bealaí tráchta, tarrthála agus oiriúnacht trealaimh.","Is réamhriachtanas é measúnú riosca a bhaineann le suíomh do choinníollacha oibriúcháin sábháilte."],"h2-kabelschlaufe":["Tá cábla cumhachta suite trasna chonair an stáitse. Cad atá ceart?","D’fhéadfadh an cábla éirí gafa le linn na gluaiseachta.","Glan an bóthar agus cosaint cáblaí leictreacha ó dhamáiste.","Bain úsáid as an cábla leis na rothaí mar thairseach bóthair.","Ardaigh an ciseán gan an t-achar urláir a sheiceáil.","Is féidir le cáblaí a ritheann nó a brúitear a bheith ina gcúis le guaiseacha leictreacha agus meicniúla."],"h2-leitungsnaehe":["Cé a shoiléiríonn na bearta cosanta ar chóras leictreach?","Ba cheart go n-oibreodh an t-ardán gar do threalamh beo.","Cinneann an duine sa chiseán trí shúile amháin.","Údaráis fhreagracha a bheith rannpháirteach agus bearta cosanta comhordaithe a chur i bhfeidhm.","Ní dhéanfar an t-achar a chinneadh ach amháin tar éis don obair tosú.","Teastaíonn bearta cosanta pleanáilte agus comhordaithe chun oibriú in aice le córais leictreacha."],"h2-funkkommunikation":["Cén fáth a gcaithfidh na comharthaí idir an t-urlár agus an ciseán a bheith soiléir?","Cabhraíonn duine ar an talamh leis an ainliú.","Ionas gur féidir le roinnt daoine treoracha contrártha a thabhairt ag an am céanna.","Ionas gur féidir an t-ísliú éigeandála a thriail gan treoracha.","Mar sin ní dhéantar gluaiseachtaí ach amháin tar éis cumarsáid shoiléir.","Laghdaíonn cumarsáid shoiléir gluaiseachtaí agus imbhuailtí míchearta nuair a bhíonn ainliú á dhéanamh."],"h2-neuebedienung":["Aistríonn tú chuig cineál eile stáitse. Cad atá ag teastáil?","Tá difríocht shuntasach idir na feidhmeanna oibriúcháin.","Treoir a bhaineann go sonrach leis an bhfeiste roimh úsáid neamhspleách.","Níl ort ach lógó na cuideachta a léamh ar an bhfeiste.","Tiomántán tástála leis an gciseán leathnaithe cheana féin gan treoracha.","Ní thagann cáilíocht amháin in ionad na treorach sa chineál feiste sonrach."],"h2-steckanschluss":["Cad ba cheart duit a sheiceáil roimh charger a nascadh?","Is gá ardán oibre aeir leictreach a mhuirearú.","Bain úsáid as aon soicéad beag beann ar riocht agus fiús.","Seiceáil nasc oiriúnach agus cábla gan damáiste de réir threoracha an mhonaróra.","Díphlugáil an breiseán cumhachta go rialta le linn luchtaithe.","Cosnaíonn naisc leictreacha oiriúnacha agus slána in aghaidh turraing leictreach agus dóiteáin."],"h2-absperrpersonal":["Téann duine isteach sa limistéar cordonáilte le linn obair ardaithe. Cad atá tú a dhéanamh?","Is féidir leat duine a fheiceáil go díreach faoin gciseán oibre.","Lean ort ag tiomáint má tá clogad cosanta á chaitheamh ag an duine.","Buail uirlis ina dtreo mar chomhartha rabhaidh.","Stop gluaiseacht chontúirteach agus glantar an limistéar.","Ní chuirtear bacainn in ionad breathnú ar an limistéar contúirte le linn oibriú."],"k2-arbeitsplanung":["Cad ba cheart a chur san áireamh san ullmhúchán oibre roimh oibríocht craein?","Níl an t-ualach, an suíomh agus an bealach iompair comhordaithe go fóill.","Ardaigh an t-ualach is troime ar dtús gan tuilleadh pleanála.","Ná marcáil ach an bealach is giorra ar urlár an halla.","Déan an acmhainn ualaigh, na slingeanna, an cosán ualaigh agus an limistéar contúirte a shoiléiriú roimh ré.","Éilíonn gluaiseacht craein pleanáilte láimhseáil ualaigh oiriúnach, bealaí sábháilte agus bearta cosanta comhordaithe."],"k2-hakenposition":["Cén chaoi a bhfuil an crúca craein suite os cionn an ualaigh sula n-ardaítear é?","Tá na pointí ceangail faoi bhun an chraen.","Chomh hingearach agus is féidir os cionn lár an domhantarraingthe de réir an stad.","Fritháireamh i bhfad go dtí an taobh ionas go luascann an t-ualach isteach níos tapúla.","In aon chás ar imeall seachtrach an ualaigh, beag beann ar lár an domhantarraingthe.","Laghdaíonn feidhmiú ingearach fórsa agus pointí ancaire oiriúnacha gluaiseacht taobhlíne agus gluaiseachtaí neamhrialaithe."],"k2-hakengabel":["Léiríonn hook ualaigh dífhoirmiúchán suntasach. Cad a bhaineann?","Is cosúil go bhfuil an duán lúbtha suas óna ghnáthstaid.","Bend an dífhoirmiúchán ar ais leis an gcéad ualach eile.","Cuir stop le hoibriú craein agus seiceálfaidh saineolaí an dubhán.","Ná ceangail ach ualaí solais agus lean ort ag obair.","Féadfaidh dífhoirmiúchán difear do shábháilteacht an hook; ní cheadaítear tuilleadh úsáide neamhúdaraithe."],"k2-zugueberlast":["Tá an t-ualach níos troime ná mar a ceapadh ar dtús. Cad atá tú a dhéanamh?","Tagann faisnéis nua meáchain chun cinn le linn ullmhúcháin.","Cuir ardú níos tapúla in ionad an chúlchiste sábháilteachta.","Déan neamhaird de mheáchan an ualaigh trí é a cheangal le pointe eile.","Déan ualach iarbhír a chinneadh agus teorainneacha ualaigh a athsheiceáil.","Éilíonn ardú sábháilte sonraí ualaigh iontaofa agus comhlíonadh na n-acmhainní ualaigh ábhartha go léir."],"k2-arbeitskorb":["An féidir le gnáthchruach craein daoine a iompar go héasca?","Is mian le duine áit ard oibre a fháil.","Ní féidir, teastaíonn saoráidí agus bearta speisialta ceadaithe le haghaidh iompar paisinéirí.","Sea, má choinníonn an duine greim ar an rópa sling.","Sea, chomh luath agus a dhéantar an stróc go háirithe go mall.","Ní cheadaítear iompar daoine ach amháin faoi choinníollacha speisialta a fhoráiltear chun na críche sin."],"k2-bruecke":["Gluaiseann craein droichead feadh cosán halla roinnte. Cad atá tábhachtach?","Fanann fostaithe faoin mbealach iompair.","Tiomáin leis an ualach díreach os cionn cinn na bhfostaithe.","Coinnigh an bealach ualaigh agus an limistéar tráchta soiléir agus slán.","Ná húsáid ach an adharc rabhaidh in ionad bearta breise.","Ní ceadmhach do dhaoine atá i mbaol a bheith faoi ualaí crochta nó ina gcosán iompair."],"k2-zweitekrane":["Oibríonn dhá chraen i limistéar forluiteach. Cad atá riachtanach?","D’fhéadfadh borradh nó ualaí imbhualadh lena chéile.","Oibríonn an dá oibreoir craein ag an am céanna gan comhaontú roimh ré.","Déantar gluaiseachtaí a luathú d'aon ghnó chun trasbhealaí a sheachaint.","Oibríochtaí a chomhordú agus bearta iomchuí a ghlacadh chun bagairtí frithpháirteacha a chosc.","Éilíonn réimsí oibre forluiteacha eagraíocht oibríochta comhordaithe agus cosaintí oiriúnacha."],"k2-pruefbuch":["Cad é an tábhacht a bhaineann leis an iniúchadh craein athfhillteach éigeantach?","Úsáidtear an meaisín go rialta in oibríochtaí.","Déanann sé an rialú oibríochta a fhorlíonadh leis an scrúdú saineolaí forordaithe.","Tagann sé go buan in ionad aon iniúchadh amhairc sula dtosaíonn an obair.","Níl sé ag teastáil ach amháin tar éis timpiste.","Tá tascanna éagsúla ag baint le cigireachtaí athfhillteacha agus rialuithe oibríochtúla leanúnacha."],"k2-absetzflaeche":["Tá an limistéar socrúcháin atá beartaithe míchothrom. Conas a ghníomhaíonn tú?","D'fhéadfadh an t-ualach dul i léig nuair a chuirtear é.","Cuir an t-ualach ar choirnéal amháin agus lig dó crochadh gan athrú.","Bunaigh nó dromchlaí oiriúnacha, ualachiompartha agus cobhsaí a ullmhú.","Cuir duine amháin faoin ualach agus é á ísliú.","Caithfidh limistéir socrúcháin tacú leis an ualach go sábháilte agus cosc ​​a chur ar thipping contúirteach nó ar ghluaiseachtaí rollta."],"k2-anfahrbereich":["Sula dtosaíonn an craein ag bogadh, tá duine amháin sa limistéar taistil. Cad atá tú a dhéanamh?","Tá an bealach bac ag duine.","Brúigh an duine i leataobh le tiomáint tástála gairid.","Bain úsáid as an lasc teorann leis féin gan iniúchadh amhairc.","Ná cuir tús le gluaiseacht ach amháin nuair atá an limistéar contúirte soiléir agus sábháilte.","Níor cheart go gcuirfeadh tiomáint agus gluaiseachtaí maighdeogacha daoine i mbaol."],"k2-schlaffseil":["Cén fáth nár cheart go n-éireodh rópa an ardaitheora le bheith bog go neamhrialaithe nuair a leagtar síos é?","Tá an t-ualach ar siúl, laghdaítear an hook a thuilleadh.","Ionas nach n-imrítear an rópa agus na crúcaí nó nach gcuirfear faoi réir luchtú neamhrialaithe iad.","Ionas gur féidir an t-ualach a tharraingt go cliathánach ansin ag an rópa.","Ionas go ndéanann slingeanna iad féin a dhícheangal ón gcruachán.","Is féidir le ródú cáblaí neamhrialaithe dul i bhfostú agus gluaiseachtaí contúirteacha ualaigh."],"k2-pendel":["Tosaíonn ualach atá á iompar ag luascadh. Cad atá ceart?","Gluaiseann an t-ualach cliathánach níos mó ná mar a ceapadh.","Déan cúiteamh le frithghluaiseachtaí tapa agus luas iomlán.","Laghdaigh gluaiseachtaí ar bhealach rialaithe agus socraigh comaitéireacht gan daoine sa limistéar contúirte.","Coinnigh an t-ualach luascadh le do lámha nochta.","Is féidir le hualaí ascalaithe dul i bhfeidhm ar dhaoine agus ar áiseanna; laghdaíonn gluaiseachtaí calma an baol."],"k2-funkakku":["Tá ceallraí lag ag rialú raidió craein. Cad a bhaineann?","D'fhéadfadh an nasc briseadh le linn ardaithe.","Ardaigh ualach go tapa sula dteipeann ar an rialú.","Má chailltear an nasc, bog an t-ualach trí tharraingt ar an sling.","Cinntigh nasc rialaithe iontaofa roimh úsáid.","Is réamhriachtanais iad rialú iontaofa agus cumarsáid le haghaidh gluaiseachtaí craein rialaithe."],"k2-mehrereanschlaeger":["Tugann beirt comharthaí éagsúla don oibreoir craein ag an am céanna. Cad atá ceart?","Tagann na comharthaí salach ar a chéile.","Cuir isteach ar ghluaiseacht agus soiléirigh freagracht shoiléir.","Is fearr comhartha an duine níos faide ar shiúl.","Leanúint ar aghaidh leis an ngluaiseacht de réir do mhothúcháin féin.","Ní mór cumarsáid shoiléir gan athbhrí a bheith ag tiománaithe craein, go háirithe nuair a bhíonn bealaí ualaigh mearbhall."],"k2-endabschaltung":["Cén fáth nár chóir lasc teorann a mhí-úsáid mar ghnáth-theorannú stróc?","Is minic a bhogtar an t-ualach suas go dtí an t-achar ardaithe uasta.","Ceadaíonn lasca teorann go ginearálta ardú níos tapúla gan infheictheacht.","Is feistí sábháilteachta iad lasca teorann agus ní chuirtear in ionad oibríocht rialaithe.","Ba chóir iad a bhualadh chomh crua agus is féidir le gach stróc.","Cosnaíonn gléasanna sábháilteachta ar chontúirtí agus ní féidir an iomarca úsáide a bhaint astu mar a bhí beartaithe."],"k2-wetterbeobachtung":["Méadaíonn an ghaoth go suntasach le ualach limistéar mór. Cad atá ag teastáil?","Feidhmíonn limistéar mór comhpháirte cosúil le seol.","Ardaigh an t-ualach níos airde i gcónaí ionas go mbeidh éifeacht níos lú ag an ghaoth.","Cuir cinn níos tanaí in ionad na slingeanna.","Déan measúnú ar theorainneacha gaoithe agus oibriúcháin agus coigeartaigh ardaithe más gá.","Is féidir le gaoth fórsaí suntasacha breise agus gluaiseachtaí luascadáin a ghiniúint, go háirithe le hualaí mór-limistéar."],"k2-ortswechsel":["Cad atá tábhachtach nuair a bhogtar craein soghluaiste go dtí suíomh nua?","Athraíonn coinníollacha fo-ithreach agus tacaíochta.","Seiceáil suíomh an tseastáin agus an tacaíocht sula bpiocann tú an t-ualach arís.","Cuir na socruithe ón suíomh roimhe seo i bhfeidhm gan seiceáil.","Déan an tacaíocht a athcheartú le linn ardaithe.","D'fhéadfadh go mbeadh coinníollacha éagsúla talún agus ualaigh tacaíochta ag gach suíomh suiteála."],"k2-betriebsbereich":["Tá craein ceaptha oibriú trasna sráide. Cad is gá a shoiléiriú?","D’fhéadfadh tríú páirtithe dul isteach sa limistéar contúirte.","Ná daingnigh an bóthar ach le adharc rabhaidh.","Glasáin riachtanacha, bearta vótála agus cosanta os comhair an mhoil.","Ardaigh an t-ualach thar fheithiclí chomh tapa agus is féidir gan é a dhaingniú.","Coscann bainistiú sábháilte tráchta riosca míchuí do thríú páirtithe ó ualaí agus gluaiseachtaí craein."],"k2-hochheben":["Tar éis an t-ardaitheoir tástála, crochadh ualach go soiléir cam. Cad atá ceart?","Is cosúil go ndearnadh míbhreithiúnas ar an bhfócas.","Lean ort ag ardú ionas go gceartóidh an éagothroime é féin.","Iarr ar dhuine amháin an t-ualach claonta a tharraingt.","Socraigh an t-ualach go sábháilte agus seiceáil an ceangaltán agus lár an domhantarraingthe arís.","Úsáidtear an t-ardaitheoir tástála chun ceangaltán mícheart agus suímh ualaigh éagobhsaí a bhrath roimh iompar."],"k2-schwebelast":["An féidir leat ualach ardaithe a fhágáil ar crochadh gan duine ag faire air?","Críochnaíonn an t-aistriú, ach tá an t-ualach fós ar an hook.","Níl, ísligh an t-ualach go sábháilte agus daingnigh an craein i gceart.","Sea, má tá an craein faoi ghlas i gcoinne bogadh ar shiúl.","Sea, chomh fada agus go bhfuil comhartha rabhaidh ar an talamh.","I bprionsabal, níor cheart ualaí ar fionraí a fhágáil gan aire."],"k2-mitnahme":["Ba mhaith le comhghleacaí marcaíocht ar ualach craein. Cad a bhaineann?","Ba cheart an t-ualach a iompar go pointe níos airde.","Ceadaítear marcaíocht má chaitheann an comhghleacaí clogad.","Ní féidir daoine a iompar ar ghnáthualaí nó a cheangal orthu.","Ceadaítear turas i gcónaí chomh fada agus is eol don tiománaí craein an comhghleacaí.","Cruthaíonn iompar daoine chomh maith le hualaí rioscaí suntasacha titim agus brú."],"k2-warnsignal":["Teipeann ar chóras rabhaidh oibriúcháin ar an gcraenach. Cad atá ceart?","Ní féidir rabhadh a thabhairt a thuilleadh roimh thiomáint as.","Déan neamhaird den chóras nuair a bhíonn an t-inneall ag rith.","Buan ionad an rabhadh ag cnagadh ar an tithíocht.","Tuairiscigh mainneachtain a bhaineann le sábháilteacht agus cuir isteach ar oibríochtaí de réir treoracha.","Caithfidh feistí rabhaidh riachtanacha a bheith feidhmiúil ionas go gcosnaítear daoine in am."],"k2-schneekante":["Is gá tacú le craein soghluaiste ar thalamh reoite, míchothrom. Cad a bhaineann?","Féadfaidh an ithir a cumas iompair a chailleadh de réir mar a leánn sí.","Déan an acmhainn ualaigh agus an staid tacaíochta a mheas faoi choinníollacha iarbhír.","Bíonn aon acmhainn imthacaí i gcónaí ar thalamh reoite.","Ná cuir ach tacaí ar chlocha beaga.","Bíonn tionchar ag teocht, taise agus struchtúr fo-ithreach ar chumas ualachiompartha suíomhanna craein."],"k2-laufkatze":["Gluaiseann tralaí i dtreo chonstaic. Conas a ghníomhaíonn tú?","Tá rud sa limistéar tiomána.","Go mall brúigh an réad ar shiúl leis an ualach.","Stop gluaiseacht in am trátha agus bain an chonstaic go sábháilte.","Tiomáin thar an chonstaic ar luas méadaithe.","Ní mór gluaiseachtaí craein a threorú sa chaoi is nach dtarlóidh aon imbhuailtí le constaicí."],"k2-anschlagaufnahme":["Ba chóir duit ualach a phiocadh ag baint úsáide as súilíní neamhshainithe. Cad atá ceart?","Níorbh fhéidir an eyelet a bheith beartaithe ach le haghaidh clúdach a fheistiú.","Tá gach eyelet oiriúnach le haghaidh ualach iomlán craein.","Ná luchtaigh an eyelet ach le beirt ag an am céanna.","Fíoraigh acmhainn ualaigh agus oiriúnacht an phointe ancaire roimh úsáid.","Níl gach eyelet atá ann cheana féin ina phointe ceangail cobhsaí le haghaidh ualaí craein."],"l2-seilbruch":["Léiríonn rópa sreang roinnt sreanga aonair briste. Cad atá ceart?","Tá na pointí briste sa limistéar rópa ualachiompartha.","Ná lean ort ag úsáid trealaimh ardaithe agus déan measúnú gairmiúil air.","Bend na foircinn sreang ar ais le do lámha nochta.","Lean ort ag baint úsáide as an rópa má tá an t-ualach éadrom go háirithe.","Is féidir le briseadh sreinge a bheith ina chritéar maidir le haischur; Ní mór rópaí damáiste a mheasúnú go gairmiúil."],"l2-schaekel":["Cad atá ríthábhachtach nuair a úsáidtear geimhle?","Ceanglaíonn geimhle an sling agus an t-ualach.","Cuir aon ingne in ionad an bolt.","Seiceáil an bhfuil acmhainn ualaigh oiriúnach, riocht gan damáiste agus boltaí cearta.","Déan meastachán ar an acmhainn ualaigh bunaithe ar an dath.","Ní mór geimhle a bheith de mhéid cuí, a úsáid go hiomlán agus sa treo luchtaithe atá beartaithe."],"l2-tragfaehigkeit":["Cad a chaithfidh tú a mheas agus tú ag úsáid snáitheanna iolracha?","Ritheann na snáitheanna ar uillinn leis an ingearach.","Níl le déanamh ach suim a chur le hacmhainn ualaigh gach snáithe mar is mian leat.","Ná crochadh ach an t-ualach ar an snáithe is éadroime.","Cuir san áireamh an cumas ualachiompartha den chineál iomlán ancaire agus uillinn.","Tá tionchar suntasach ag uillinn claonta agus líon éifeachtach na snáitheanna ar an ualach incheadaithe."],"l2-schweissnaht":["An féidir pointe ancaire seiftithe a tháthú chuig ualach?","Níl aon phointí bailithe ainmnithe oiriúnacha don ualach.","Ná húsáid ach pointí ancaire atá deartha agus ceadaithe i gceart.","Is leor aon seam weld gan tástáil.","Cuir crúca isteach trí oscailt sa leathán miotail.","Ní mór a chruthú go bhfuil pointí ancaire oiriúnach do na fórsaí a bhaineann le tógáil."],"l2-einseitig":["Tá ualach i bhfad níos troime ar thaobh amháin. Conas a théann tú faoi?","Tá lár an domhantarraingthe lasmuigh den ionad geoiméadrach.","Fág an fad céanna ar gach snáithe beag beann ar lár an domhantarraingthe.","Déan lár an domhantarraingthe a chinneadh agus an suíomh a choigeartú dá réir sin.","Ar dtús ardaigh an t-ualach go dtí airde iomlán ardaithe.","Má tá lár an domhantarraingthe lasmuigh den lár, féadfaidh ualaí barr gan choinne nó is féidir snáitheanna aonair a ró-ualach."],"l2-kettenriss":["Cad a bhaineann le sling slabhra le scoilteanna infheicthe?","Tá crack i gceann de na naisc slabhra.","Marcáil an crack le péint agus tóg gan athrú é.","Wrap an nasc le sreang agus athúsáid é.","Bain an slabhra láithreach agus cuir an duine freagrach ar an eolas.","Is damáiste a bhaineann le sábháilteacht iad scoilteanna sna naisc slabhra ualachiompartha agus tá gá le díchoimisiúnú."],"l2-lastfuehrung":["Conas a iompraíonn tú ualach mór nuair a bhíonn riosca rothlaithe ann?","Is féidir leis an ualach luascadh taobh le linn ardaithe.","Úsáid gléasanna treorach cuí agus achar sábháilte.","Coinnigh an t-ualach go díreach idir do lámha agus tú ag tiomáint.","Céim faoin ualach agus é a ailíniú ó thíos.","Ní ceadmhach do threoir ualaigh a bheith ina chúis le lámha nó coirp dul isteach sa chrios contúirte."],"l2-schnueren":["Cad atá tábhachtach agus na lásaí á gceangal?","Tá an sling treoraithe timpeall comhpháirte.","Glac leis an toilleadh ualaigh céanna le haon chineál eile ancaire.","Breathnaigh ar oiriúnacht an chineáil ceangail agus an t-ualach incheadaithe de réir na marcála.","Tarraing an gléas sling le chéile go pointe ar bith gan seiceáil.","Is féidir leis an gcineál ceangail lacing an acmhainn ualaigh incheadaithe a athrú agus ní mór é a úsáid i gceart."],"l2-winkelmesser":["Cén fáth nach féidir leat neamhaird a dhéanamh ar uillinn shnáithe chomhréidh?","Ritheann dhá líne sling beagnach go cothrománach leis an ualach.","Déanann uillinn chomhréidh an snáithe níos láidre go huathoibríoch.","Déantar an t-ualach a dháileadh go cothrom i gcónaí beag beann ar an uillinn.","Is féidir le fórsaí ard-snáithe an acmhainn ualaigh incheadaithe a shárú.","De réir mar a mhéadaíonn an uillinn leis an ingearach, méadaíonn an strus ar na snáitheanna."],"l2-heisse-last":["Cad is gá duit a sheiceáil le haghaidh ualach te?","Rinneadh cóireáil teasa ar chuid cruach le déanaí.","Breathnaigh ar theorainneacha teochta na slingeanna agus roghnú oiriúnach.","Is féidir le gach sling teicstíle aon teocht a sheasamh.","Is cuma faoin lipéadú nuair a bhíonn sé te.","Féadann teocht difear a dhéanamh d'acmhainn ualaigh incheadaithe na slingeanna."],"l2-abstand":["An féidir leat do mhéara a chur faoin ualach agus é á leagan síos?","Ba chóir go dtiocfadh an t-ualach i dtír ar dhromchla le cruinneas milliméadar.","Sea, má chaitheann tú lámhainní oibre.","Ní féidir, coinnigh fad uait agus bain úsáid as áiseanna cuí.","Sea, má tá an ghluaiseacht craein go háirithe mall.","Féadfaidh codanna den chorp idir an t-ualach agus an bonn a bheith gafa."],"l2-verbindung":["Níl nasc nasctha den slabhra sling faoi ghlas. Cad a bhaineann?","Tá an ceanglóir ar iarraidh.","Bain úsáid as an bolt gan an glas nuair nach bhfuil aon duine ag faire.","Séalaigh an eilimint le téip ghreamaitheach.","Ná buail go dtí go bhfuil an ceanglóir daingnithe i gceart.","Ní mór eilimintí ceangail a dhaingniú go hiomlán agus de réir a ndearadh."],"l2-lasthaken":["Cad a dhéanann tú a sheiceáil agus tú ag crochadh ar hook craein?","Ba chóir roinnt slingeanna a threorú isteach sa hook.","Cinntigh feistiú slán agus oiriúnacht na gcrúcaí agus an chrochta.","Cuir sliotáin ar bharr an chromáin.","Cuir comhionannas vótaí cábla in ionad an ghlais hook.","Ní mór an fórsa a chur i bhfeidhm mar atá beartaithe sna limistéir ainmnithe."],"l2-fasern":["Léiríonn strap ardaithe garbhú tromchúiseach agus damáiste snáithíní. Cad atá ceart?","Tá damáiste feiceálach ag snáithíní tacaíochta.","Clúdaigh an damáiste le snaidhm eile.","Scar an strap ardaithe agus iarr ar speisialtóir é a sheiceáil.","Ansin ardaigh an t-ualach níos tapúla.","Is féidir le snáithíní ualachiompartha damáiste laghdú suntasach a dhéanamh ar chumas ualachiompartha strap ardaithe."],"l2-anheben":["Cad a bhaineann díreach tar éis an chéad ceintiméadar ardaithe?","Níl an t-ualach ach ardú as a bhonn.","Tarraing an t-ualach go dtí a airde iomlán gan smacht.","Seiceáil faoin ualach an bhfuil teannas ar na slingeanna.","Seiceáil suíomh an stad, cothromaíocht agus iompar gluaiseachta.","Fágann ardaitheoir tástála rialaithe go bhféadfaí éagobhsaíocht a fheiceáil roimh iompar breise."],"l2-lastgewichte":["Níl an meáchan ualaigh anaithnid. Cad atá ceart?","Níl aon mharcáil meáchain ag an gcomhpháirt.","Déan an meáchan inlódála a chinneadh sula roghnaítear slingeanna.","Déan meastachán ar an meáchan bunaithe ar dhath an ualaigh.","Bain úsáid as aon sling fad dúbailte.","Gan meáchan aitheanta nó cinnte go hiontaofa, ní féidir oiriúnacht na slingeanna a sheiceáil le cinnteacht."],"l2-lose-teile":["Tá uirlisí scaoilte ar an ualach atá le tógáil. Cad atá tú a dhéanamh?","D'fhéadfadh uirlisí titim nuair a ardú.","Coinnigh uirlisí le lámh amháin agus tú ag tiomáint.","Bain rudaí scaoilte amach nó déan iad a dhaingniú go héifeachtach sula n-ardaítear iad.","Ardaigh an t-ualach beagán níos tapúla ionas nach duillíní aon rud.","Is féidir le rudaí scaoilte titim agus daoine sa cheantar a chur i mbaol."],"l2-wind":["Tá ualach mór ceangailte le gaoth láidir. Cad a bhaineann?","Tugann an chomhpháirt limistéar dromchla mór don ghaoth chun ionsaí.","Ardaigh an t-ualach gan smaoineamh ar ghluaiseachtaí luascadh.","Ba cheart do dhaoine breise an t-ualach a shealbhú go díreach.","Déan measúnú ar choinníollacha gaoithe agus staon ó ardú má tá an cás neamhshábháilte.","Is féidir le fórsaí gaoithe tionchar a imirt ar threoir ualaigh agus ar chobhsaíocht le linn iompair."],"l2-unterlage":["Cén fáth a bhfuil tábhacht le doiciméid oiriúnacha agus tú ag baint scoite amach?","Rollfadh ualach cruinn ar an talamh.","Cuir an t-ualach síos go daingean agus slán é in aghaidh rollta más gá.","Fág an t-ualach ina sheasamh go díreach ar na sliotáin.","Ná brúigh na doiciméid faoin ualach ach amháin tar éis dóibh a bheith leagtha síos.","Coscann tacaí oiriúnacha tipping agus gluaiseachtaí nach dteastaíonn agus iad ag leagan síos."],"l2-transportweg":["Cad is gá a chomhordú sula n-iompraítear an t-ualach?","Bogtar an t-ualach thar roinnt réimsí oibre.","Díreach fad ionchais an mhoil.","Conair ualaigh shábháilte, cumarsáid agus bacainní riachtanacha.","Ba chóir do dhuine amháin an bealach a thaispeáint faoin ualach.","Teastaíonn bealaí sábháilte tráchta agus comhordú soiléir chun ualaí a iompar."],"l2-schutzschlauch":["Cad ba cheart duit aird a thabhairt air nuair a bhíonn slingeanna á n-úsáid le píobán cosanta?","Tá banna i gcoinne imeall garbh.","Cuirtear cosaint imeall oiriúnach in ionad aon éadach tanaí.","Baineann píobán cosanta amach aon teorainn ualaigh incheadaithe.","Roghnaigh trealamh cosanta de réir riachtanais oiriúnachta agus iarratais.","Caithfidh trealamh cosanta an t-ábhar, an imeall agus an t-ualach atá beartaithe a mheaitseáil."],"l2-reinigung":["Bhí strap ardaithe éillithe le ceimiceán anaithnid. Cad atá ceart?","Ní féidir an téip a mheas go soiléir a thuilleadh.","Stop a úsáid agus comhoiriúnacht nó riocht a shoiléiriú go gairmiúil.","Glan le tuaslagóir ar bith agus lean ort ag ardú láithreach.","Déan neamhaird den cheimiceán agus an téip tirim.","Is féidir le ceimiceáin difear do neart na slingeanna teicstíle."],"l2-aufhaengung":["Cad a dhéanann tú seiceáil le haghaidh snáitheanna iolracha ar an nasc fionraí?","Cuirtear dhá shraith le chéile i bhfionraí.","Is féidir le snáithe bogadh isteach i mbarr an chromáin de réir toil.","Caithfidh na heilimintí nascála go léir a bheith oiriúnach agus eagraithe mar a bheartaítear.","Is féidir fáinne le crack a úsáid le haghaidh ualaí beaga.","Caithfidh eilimintí stad agus nascála a bheith ualachiompartha agus eagraithe i gceart."],"l2-einweiserrolle":["Cad a bhaineann mura bhfuil aon líne radhairc ag an ionsaitheoir agus an t-oibreoir craein?","Cuireann iompróir bac ar radharc an phointe titim.","Comhordú trí ghlaoch ar roinnt daoine gan fhreagracht.","Bog an t-ualach bunaithe ar thorann gan teagasc.","Eagraigh cumarsáid shoiléir shlán agus cuir stop leis mura bhfuil sé soiléir.","Ní mór an easpa infheictheachta a chúiteamh trí chomhordú éifeachtach agus cumarsáid shlán."],"l2-ausserbetrieb":["Réitíodh sling millte. Cad eile atá tábhachtach?","Tá sé fós inrochtana go héasca in éineacht le hacmhainní atá réidh le húsáid.","A shlánú i gcoinne tuilleadh úsáide de thaisme agus an duine atá freagrach a chur ar an eolas.","Cuir an táirge gan mharcáil ar ais chuig an bhfardal.","Ná húsáid arís é ach nuair a bhíonn ualach an-éadrom á iompar agat.","Ní mór slingeanna caite a chosaint go hiontaofa roimh úsáid bhreise."],"b2-schwenkradius":["Cén fáth a bhfuil ga luascadh cúil tochailteora ríthábhachtach?","Gluaiseann an t-eireaball thar limistéar oibre teoranta.","Is féidir le tríú páirtithe a bheith gafa leis an bhforstruchtúr luascadh.","Níl aon tionchar ag an ga swing ar dhaoine in aice leis an meaisín.","Ní ghluaiseann an cúil i gcónaí ach sa treo taistil.","Nuair a bhíonn pivoting, tagann limistéar contúirte chun cinn taobh thiar den mheaisín freisin."],"b2-verkehrseinweiser":["Conas a dhéantar gluaiseacht tiomána a dhaingniú nuair a bhíonn an infheictheacht doiléir?","Caithfidh tochaltóir ainliú taobh thiar de chonstaic.","Tiomáint gan comharthaí an chomharthaí a fheiceáil.","Más gá, eagraigh treoir chuí le cumarsáid shoiléir.","Ná déan cúlú slán ach amháin le honking uair amháin.","Teastaíonn bearta éifeachtacha chun imbhuailtí agus gabháil a chosc ó bhealaí mearbhall."],"b2-standplatz":["Cad a bhaineann le seastán tochailteora ar fhána?","Tá fána ar an urlár agus féadfaidh sé a bheith sleamhain.","Is féidir leis an meaisín síneadh chomh fada agus is maith leis ag aon incline.","Socraigh an tochaltóir i gcónaí ar shraith scaoilte talún.","Seiceáil cobhsaíocht agus teorainneacha oibriúcháin an mheaisín roimh úsáid.","Tá tionchar suntasach ag fána fána agus fo-ithir ar chobhsaíocht."],"b2-oberleitung":["Cén fáth a bhfuil gá le fad an bhorrtha ó línte cumhachta a phleanáil?","Is féidir leis an borradh teacht in aice leis an gcábla nuair a sclóine.","Tá flashover leictreach indéanta freisin gan teagmháil dhíreach.","Ní féidir ach an buicéad leictreachas a sheoladh, ní an borradh.","Le ithir thirim, tá gach achar sábháilte go huathoibríoch.","Ní mór teorainneacha úsáide agus achair chosanta a shoiléiriú sula dtéann tú i dteagmháil le córais leictreacha."],"b2-fremdperson":["Téann duine atá ag dul thart isteach sa láithreán tógála sa limistéar panning. Cad atá ceart?","Seasann an duine go tobann in aice le buicéad an tochailteora.","Ardaigh an sluasaid suas agus luascadh thar an duine é.","Cuir stop leis an ngluaiseacht láithreach agus bíodh an limistéar glanta.","Just a leanúint ar aghaidh chun féachaint ar an duine as an fhuinneog taobh.","Níor cheart go mbeadh daoine sa limistéar contúirte i mbaol mar gheall ar ghluaiseachtaí oibre."],"b2-parkstellung":["Conas a dhaingnítear meaisín crith talún tar éis don obair a bheith críochnaithe?","Tá an tochaltóir fós gan duine ar an láithreán tógála.","Fág an spúnóg ag leibhéal an chinn.","Lig don inneall rith gan duine ar bith.","Cuir an trealamh oibre síos, déan an meaisín a dhaingniú agus cosc ​​a chur ar úsáid neamhúdaraithe.","Laghdaíonn páirceáil cheart gluaiseacht thimpiste agus rochtain neamhúdaraithe."],"b2-eigenlast":["Cén fáth a bhfuil teorainneacha trealaimh ríthábhachtach agus tú ag tógáil le tochaltóir?","Tá ualach trom le fagháil ar an mbórd.","Seachas sin, féadfar cobhsaíocht agus cumas ualaigh incheadaithe a shárú.","Is féidir le haon mheaisín aon ualach a ardú chomh fada agus a oireann an buicéad.","Ní chinneann ach fad an rópa sling an riosca.","Braitheann faisnéis faoi thoilleadh ardaithe agus ualaigh ar an trealamh agus ar an staid iarratais."],"b2-untergrundhohlraum":["D'fhéadfadh an t-urlár os cionn sean-íoslach a bheith log. Cad atá tú a dhéanamh?","Ba chóir duit an tochaltóir a thiomáint isteach sa cheantar.","Trasnaigh an láthair le móiminteam uasta.","Soiléirigh an toilleadh ualaigh agus na cuais a d'fhéadfadh a bheith ann sula dtiomáineann tú ar aghaidh.","Níl ort ach ualach trom a chur ar an dromchla.","Is féidir le cuasáin titim faoi mheáchan an mheaisín agus cuirfidh siad faoi deara an meaisín a thuairteáil."],"b2-feuchtigkeit":["Tar éis báisteach throm éiríonn an claífort bog. Cad atá ceart?","Oibríonn tochaltóir gar d’imeall an chlaífoirt.","Bog an meaisín níos gaire don imeall chun an teacht a mhéadú.","Déan neamhaird de na hathruithe go dtí deireadh an tsift.","Athmheasúnú a dhéanamh ar choinníollacha ithreach agus cobhsaíochta.","Is féidir le treá taise an cumas ualachiompartha agus cobhsaíocht na gclaífort a athrú."],"b2-bodenprobe":["Cén fáth a gcaithfear na pleananna píblíne a sheiceáil roimh thochailt?","D'fhéadfadh cáblaí a bheith ag rith faoin tochailt atá beartaithe.","Ionas gur féidir línte a aithint agus bearta slándála oiriúnacha a phleanáil.","Ionas gur féidir tochailt a dhéanamh níos tapúla, go neamhspleách ar chórais tríú páirtí.","Toisc nach féidir meaisíní a úsáid in aice le cáblaí riamh.","Éilíonn línte soláthair faoi thalamh soiléiriú suímh iontaofa roimh obair thochailte."],"b2-maschinenzugang":["Cad a bhaineann le dul isteach agus amach as an meaisín gluaiste talún?","Tá an meaisín ar thalamh míchothrom.","Sleamhnaigh síos an líne hiodrálach amach as an gcábán.","Bain úsáid as céimeanna sainithe agus cinntigh bonn slán.","Léim ar an ngéag sclóine agus an meaisín ag rith.","Laghdaítear an baol go dtitfidh agus go mbrisfidh tú ar dhreapadh sábháilte agus ar stadphointí oiriúnacha."],"b2-kupplung":["Conas backhoe nua a sheiceáil tar éis a shuiteáil?","Tá an buicéad ceangailte tríd an cúplóir tapa.","Ná déan ach an spúnóg a mheas ó radharc níos faide.","Céim go díreach faoin spúnóg ardaithe.","Glasáil ceart agus céimeanna rialaithe forordaithe a chinntiú.","Is féidir le ceangaltáin atá faoi ghlas go mícheart teacht scaoilte agus daoine a chur i mbaol."],"b2-hydraulikwartung":["Cén fáth nach gceadaítear línte hiodrálacha a oscailt faoi bhrú?","Is gá píobán a athsholáthar.","Is féidir le sreabhán éalú a bheith ina chúis le gortuithe tromchúiseacha mar gheall ar bhrú ard.","Cuireann an brú cosc ​​​​ar ola ó éalú i gcónaí.","Is féidir líne oscailte a sheiceáil go sábháilte le do lámha.","Is féidir le sreabhán ardbhrú dul isteach i bhfíochán agus éilíonn sé faoiseamh brú sábháilte."],"b2-fahrweg":["Caithfidh tú tiomáint thar dhroichead tógála sealadach. Cad atá á sheiceáil agat?","Níl an droichead deartha ach le haghaidh ualaí áirithe.","Cibé an bhfuil dath an droichid ag teacht leis an meaisín.","Cumas luchtaithe agus oiriúnacht do mheáchan agus toisí an mheaisín.","Ach amháin an bhfuil carr éadrom tiomáinte cheana féin ar an droichead.","Ní fhéadfar struchtúir shealadacha a úsáid ach amháin laistigh dá gcumas ualachiompartha cruthaithe."],"b2-baggertransport":["Cad atá tábhachtach nuair a bhíonn tochailteoir á iompar ar lódóir íseal?","Tógtar an meaisín go dtí an chéad láithreán tógála eile.","Lig don trealamh oibre sní isteach go scaoilte thar an imeall.","Coinnigh an doras cábáin ar oscailt agus tú ag tiomáint.","Déan an meaisín a dhaingniú de réir sonraíochtaí iompair agus seiceáil an trealamh luchtaithe.","Cuireann glais iompair agus áiseanna lódála oiriúnacha cosc ​​ar shleamhnú agus titim."],"b2-schaufelfuellung":["Cén fáth nach bhfuil cead ag lódóir roth tiomáint go tapa agus an buicéad ardaithe ard?","Tá an t-ualach trom agus tá an talamh míchothrom.","Is féidir le meáchanlár ard cur leis an mbaol fadhbanna tipping agus infheictheachta.","Cobhsaíonn an buicéad go huathoibríoch ag luasanna ard.","Níl airde an tsluasaigh ábhartha maidir le cobhsaíocht.","Is gnách go n-eascraíonn lárionad ardaithe domhantarraingthe cobhsaíocht nuair a bhíonn tú ag tiomáint agus ag cúinneáil."],"b2-fussgaenger":["Conas a iompraíonn tú féin agus tú ag ainliú in aice le coisithe?","Is cosán é rochtain an láithreáin tógála freisin.","Bain úsáid as an sluasaid chun coisithe a threorú go dtí an taobh.","Ná déan an ghluaiseacht tiomána ach amháin nuair atá an limistéar soiléir agus inbhainistithe go sábháilte.","Just honk uair amháin agus tiomáint go mall gan infheictheacht.","Ní mór trácht feithicle agus paisinéirí a dheighilt go héifeachtach nó a chomhordú go sábháilte."],"b2-ueberlastwarnung":["Nuair a bhíonn sé ardaithe, tuairiscíonn an meaisín ró-ualach. Cad atá tú a dhéanamh?","Sroicheann ualach ardaithe na teorainneacha ceadaithe.","Múch an rabhadh agus lean ar aghaidh ag ardú gan athrú.","Déan an t-ualach níos doichte go tobann agus an meaisín ag rith.","Stop gluaiseachtaí contúirteacha agus ceartaigh an staid ualaigh go sábháilte.","Léiríonn rabhaidh ró-ualaithe sáruithe féideartha teorann agus rioscaí cobhsaíochta."],"b2-wasserleitung":["Agus é ag tochailt, aimsítear píopa anaithnid. Cad a bhaineann?","Níl an líne léirithe sna pleananna tógála.","Cuir stop leis an obair sa limistéar difear agus aithníodh an líne go gairmiúil.","Bain triail as an líne a bhogadh leis an sluasaid tochailteora.","Lean ar aghaidh ag tochailt go díreach faoin líne gan seiceáil.","Is féidir le línte anaithnide a bheith ina gcúis le guaiseacha leictreacha, gáis nó uisce."],"b2-hangefahrt":["Conas a thiomáineann tú tochaltóir ar fhána géar?","Téann an bealach pleanáilte feadh fána.","Tiomáin trasna an fhána beag beann ar theorainneacha an mhonaróra.","Breathnaigh ar chlaonadh incheadaithe agus ar stíl tiomána fhorordaithe an mheaisín.","Swing an borradh i bhfad amach chun an fheithicil a chothromú.","Braitheann an fána incheadaithe ar an meaisín, ar an dromchla agus ar fhaisnéis an mhonaróra."],"b2-schlechtebeleuchtung":["Nuair a bhíonn tú ag obair i bpoll dorcha, níl an infheictheacht leordhóthanach. Cad atá ceart?","Is ar éigean a fheiceann tú daoine agus constaicí.","Luas tochailt a mhéadú chun an oibríocht a chríochnú go tapa.","Ná húsáid na soilse agus an t-inneall ag rith.","Stop an obair go dtí go bhfuil na limistéir chontúirt le feiceáil go leor.","Tá gá le hinfheictheacht shábháilte ar limistéir tiomána agus oibre le haghaidh gluaiseachtaí meaisíní rialaithe."],"b2-kettenverschleiss":["Le linn an tseiceáil laethúil, tugtar faoi deara rian bolb damáiste. Cad atá tú a dhéanamh?","Léiríonn nasc slabhra damáiste soiléir.","Ná lean ar aghaidh ag baint úsáide as an meaisín neamhrialaithe agus tuairiscigh aon damáiste.","Lean ort ag tiomáint ar ardluas ionas go díríonn an slabhra amach.","Lean ort ag obair ar thalamh bog gan seiceáil.","Is féidir le damáiste don tiomáint dochar a dhéanamh do inrialaitheacht agus do chobhsaíocht."],"b2-ladearbeiten":["Luchtaíonn tú trucail leis an tochaltóir. Cad atá tábhachtach?","Fanann an tiománaí trucail in aice leis an limistéar luchtaithe.","Swing an buicéad thar chábán an tiománaí gan chosaint.","Cosc a chur ar dhaoine fanacht sa limistéar contúirte agus próisis a chomhordú.","Tosaigh luchtú gan cumarsáid a dhéanamh leis an tiománaí.","Nuair a bhíonn tú ag luchtú tá an baol ann ó ábhar titim agus gluaiseachtaí luascadh."],"b2-arbeitsunterbrechung":["Cuireann tú isteach ar obair thochailte le haghaidh cruinnithe. Cad a bhaineann?","Ba chóir go seasfadh an meaisín ar feadh roinnt nóiméad gan a bheith á oibriú.","Fág an sluasaid ardaithe mar mharcóir.","Fág an meaisín gan duine ina choinne agus an tiomántán tarraingthe gafa.","Socraigh an gléas go sábháilte agus slán an meaisín in aghaidh úsáide neamhbheartaithe.","Éilíonn fiú cur isteach gearr staid mheaisín shábháilte."],"b2-rollmaterial":["Is féidir le hábhar scaoilte titim nuair a iompraítear é leis an lódóir roth. Cad atá ceart?","Tiomáineann an lódóir gar d'fhostaithe.","Pioc suas an t-ualach go sábháilte agus roghnaigh stíl tiomána sábháilte le seasamh sluasaid oiriúnach.","Ardaigh an sluasaid chomh hard agus is féidir ionas go mbeidh radharc soiléir ar an gceantar máguaird.","Pioc suas an t-ualach gan teorainn a chur leis an líonadh buicéad.","Is féidir le hualaí scaoilte, suímh ard buicéad agus droch-infheictheacht daoine agus trácht a chur i mbaol."]};
